UPDATE submission_sites SET rw_source_lead='Curated rather than crowdsourced, and priced like it: a monthly subscription just to be considered.', rw_what_you_get='A dofollow listing that costs $9.99 a month or $150 lifetime, reviewed in a median of five working days.', rw_you_need='["A working public URL and a payment","A product pricing tier"]', rw_eligibility='You need a live public tool and to pay. Staging URLs and anything behind a login wall are refused.', rw_submit_steps='["1 Give three fields: a name, a URL and a plan. They write the listing from your site and you override it under Details if you want.","2 Set the pricing tier — Free, Freemium, Free Trial or Paid — describing your product, not the listing fee.","3 Accept the listing fee: a $9.99 monthly subscription marked required, with a $150 lifetime deal as the alternative.","4 Wait out the review. Median review is five working days; the directory is curated, not crowdsourced."]', rw_submit_requirements='["A payment of $9.99 a month or $150 lifetime","A working public URL and a product pricing tier","Optional features, links, logo, hero image and video"]', rw_rejection_reasons='["Staging URLs and anything behind a login wall"]', rw_gotchas='["The listing fee is a recurring subscription, so the listing disappears when you stop paying unless you buy the lifetime deal.","Add-ons run $150 to $300 each and the checkout totals them automatically — read the summary before paying.","They write your listing from your site, so a thin homepage becomes a thin listing."]', rw_faq='[{"question":"How long does ToolDirectory.AI approval take?","answer":"About a week; median review is five working days."},{"question":"How much does it cost to submit to ToolDirectory.AI?","answer":"$9.99 a month or $150 lifetime, with add-ons up to $300."},{"question":"Does a ToolDirectory.AI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 47."},{"question":"Do I need to link back to ToolDirectory.AI?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Staging URLs and anything behind a login wall."}]', rw_summary='ToolDirectory.AI is a paid-only $9.99/month dofollow AI directory with no backlink and a five-day median review. Domain rating is 47.', rw_fact_points='["Median review of five working days","Paid-only subscription or $150 lifetime, dofollow","No badge or return link is expected","Accepts AI tools and SaaS"]', rw_submission_checks='["The fee recurs unless you buy lifetime.","Add-ons are totalled automatically.","Your homepage becomes the listing copy."]', rw_seo_title='ToolDirectory.AI: $9.99/mo Dofollow, DR 47', rw_seo_description='How to submit to ToolDirectory.AI: $9.99/month dofollow listing, no backlink. Curated review — 2026-11-16 snapshot.' WHERE slug='tooldirectory-ai';
