UPDATE submission_sites SET rw_source_lead='A $19.99 fee to review and publish your listing, refunded if declined — with a nofollow link the policy calls dofollow.', rw_what_you_get='A nofollow listing written from your site, published within two days of a $19.99 payment or refunded.', rw_you_need='["An active AI product on its own official domain","A clear use case and first-party information that verifies the claims","A Google account"]', rw_eligibility='You need a real, verifiable AI tool. Duplicate, inaccessible, misleading, unlawful or unsupported submissions are refused.', rw_submit_steps='["1 Sign in. Continue with Google on submit is the only option offered there.","2 Add the essentials: a website link, your email and a short description up to 500 characters. They write the profile from your site.","3 Pay. Continue to checkout opens Stripe for $19.99; nothing is reviewed before payment.","4 Review. They check the site and publish an accepted listing within two days, or refund it."]', rw_submit_requirements='["A website link and email","A short description up to 500 characters","A $19.99 payment"]', rw_rejection_reasons='["Duplicate, inaccessible, misleading, unlawful or unsupported submissions"]', rw_gotchas='["The policy and submit page promise a dofollow link, but every listing opened carried rel=nofollow — check a live listing before paying for the link.","Payment comes before review. A decline is refunded, but nothing is looked at until you have paid.","Featured status is editorial and is not for sale."]', rw_faq='[{"question":"How long does Public Prompts approval take?","answer":"One to two days; publication is within two days of payment."},{"question":"How much does it cost to submit to Public Prompts?","answer":"$19.99 once plus tax via Stripe before review, refunded in full if declined or unpublishable."},{"question":"Does a Public Prompts listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 44, despite the dofollow claim."},{"question":"Do I need to link back to Public Prompts?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Duplicate, inaccessible, misleading, unlawful or unsupported submissions."}]', rw_summary='Public Prompts is a paid $19.99 nofollow AI directory with no backlink, promising dofollow in policy but showing nofollow on listings. Domain rating is 44.', rw_fact_points='["Two-day review after payment","Paid-only at $19.99, nofollow","No badge or return link is expected","Accepts AI tools"]', rw_submission_checks='["The promised link is nofollow in samples.","Payment precedes review.","Refunds apply on decline."]', rw_seo_title='Public Prompts: $19.99 Listing, DR 44', rw_seo_description='How to submit to Public Prompts: $19.99 one-time nofollow listing, no backlink. Dofollow claim from the 2026-11-16 snapshot.' WHERE slug='public-prompts';
