UPDATE submission_sites SET rw_source_lead='A hand-vetted list capped at 1,000 tools, rented by the month rather than submitted to.', rw_what_you_get='A dofollow listing that lasts only while a monthly payment continues — a rental, not a permanent placement.', rw_you_need='["A functional tool that delivers what it promises","An account, a payment method, a tool URL and an email"]', rw_eligibility='You need a working product that is not an infoproduct. Anything broken at review time is refused.', rw_submit_steps='["1 Ignore the guessable submit path — it 404s. Every working Submit control points at the tool-create route, which redirects to signup.","2 Pick a plan before describing anything. The first screen takes only a tool URL and an email, with the $1-first-month plan already selected; the yearly option is $59.99.","3 Agree to the checklist: the tool works, delivers what it promises and is not an infoproduct.","4 Wait for a human. The card is charged only once the tool is reviewed and accepted, so a rejection costs nothing."]', rw_submit_requirements='["A tool URL and email and an active subscription","A working product that is not an infoproduct"]', rw_rejection_reasons='["Infoproducts, ruled out by name in their checklist, and anything not working at review time"]', rw_gotchas='["This is a rental: the listing and dofollow link exist only while the monthly payment continues — cancelling takes back the link.","The submit path everyone guesses returns a 404; the working door is the tool-create route that bounces to signup, and nothing on the site says so.","You commit to a plan on the first screen, having entered nothing about the product but its URL."]', rw_faq='[{"question":"How long does 1000.tools approval take?","answer":"No review time is published; a human reviews before charging."},{"question":"How much does it cost to submit to 1000.tools?","answer":"$1 the first month then $5.99 a month, or $59.99 a year. The card is charged only after a human accepts the tool."},{"question":"Does a 1000.tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 38, but only while the subscription runs."},{"question":"Do I need to link back to 1000.tools?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Infoproducts and anything not working at review time."}]', rw_summary='1000.tools is a paid monthly dofollow listing with no backlink — a rental where the link disappears on cancellation. Domain rating is 38.', rw_fact_points='["Human review, no published time","Paid monthly, dofollow while subscribed","No badge or return link is expected","Accepts working SaaS, AI tools and extensions"]', rw_submission_checks='["The link is rented, not owned.","The real submit route 404s if guessed.","The plan is chosen on screen one."]', rw_seo_title='1000.tools: $5.99/mo Dofollow Rental, DR 38', rw_seo_description='How to submit to 1000.tools: $1-first-month dofollow rental, no backlink. Link lasts while subscribed — 2026-11-16 snapshot.' WHERE slug='1000-tools';
UPDATE submission_sites SET rw_source_lead='An AI tools directory with no free lane: the cheapest way in is fifteen dollars, paid once.', rw_what_you_get='A dofollow listing from $15 once, with no backlink and tiered review speed.', rw_you_need='["A payment — there is no free tier","An overview of at least 50 and features of at least 100 characters","One category and up to five tags from their lists"]', rw_eligibility='You need to pay and an AI tool. Anything that is not AI, or anyone not paying, is out — the form ends at a checkout.', rw_submit_steps='["1 Open the form at the submit-tools route. One long page, no account step; the short submit path 404s.","2 Your information: your name and email as the submitter, not the product.","3 Tool details: a name, URL, an overview of 50 to 1,000, features and use cases of 100 to 3,000 in Markdown, pricing, platforms, one category and up to five tags.","4 Links and plan: optional social and blog links, then one of three paid tiers, then Submit AI Tool and a Stripe checkout."]', rw_submit_requirements='["Payment from $15 once via Stripe","A submitter name and email and a tool name and URL","An overview of 50 to 1,000 and features of 100 to 3,000 characters","One of twelve categories and up to five tags"]', rw_rejection_reasons='["Anything that is not an AI tool, and anyone not paying — the form ends at a Stripe checkout"]', rw_gotchas='["There is no free tier anywhere — the whole form fills without mentioning money, then ends in three paid cards and a checkout.","The name field rejects dashes and asks for spaces or underscores instead, a problem for a product whose name has one.","The working form is at the submit-tools path; the obvious short path renders their 404 page."]', rw_faq='[{"question":"How long does AI Center approval take?","answer":"Three to five days; Basic reviews within three business days, higher tiers are faster."},{"question":"How much does it cost to submit to AI Center?","answer":"$15 Basic with review in three days; $45 Standard adds 24-hour approval and a homepage feature; $65 Premium adds two-hour approval and a blog post. Stripe only."},{"question":"Does an AI Center listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 37."},{"question":"Do I need to link back to AI Center?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Non-AI tools and anyone not paying."}]', rw_summary='AI Center is a paid-only $15+ dofollow AI directory with no backlink, whose form hides the price until the Stripe checkout. Domain rating is 37.', rw_fact_points='["Three-to-five-day review","Paid-only from $15, dofollow","No badge or return link is expected","Accepts AI tools only"]', rw_submission_checks='["No free tier — the price appears at checkout.","The name field rejects dashes.","Use the submit-tools path, not the short one."]', rw_seo_title='AI Center: $15 Dofollow Listing, DR 37', rw_seo_description='How to submit to AI Center: $15+ one-time dofollow AI listing, no backlink. Hidden paywall from the 2026-11-16 snapshot.' WHERE slug='aicenter';
UPDATE submission_sites SET rw_source_lead='A curated tools directory whose free lane is honest about the queue: over 180 days at current pace.', rw_what_you_get='A dofollow listing on free with three links, if you can wait past 180 days and survive a slot check.', rw_you_need='["An account via Google, GitHub or email","An icon and a wide image each 1MB or less"]', rw_eligibility='You need an account and media. Anyone needing a listing inside six months is out on free, as is anything outside their AI-and-productivity categories.', rw_submit_steps='["1 Sign in with Google, GitHub or email and password; submit redirects to login until signed in.","2 Details: a link, name, categories, tags, a short description, a Markdown introduction, then an icon and a wide image as uploads.","3 Payment: three cards. The free one sits below the two paid ones with the badge snippet, a Verify button and Submit to review.","4 Publish. The free status moves to Pending and the card becomes Go dashboard and Wait; no review window is stated."]', rw_submit_requirements='["An account and a product name and URL","Categories and tags from their lists and a short description","A Markdown introduction","A 1:1 icon and a 16:9 image, PNG or JPEG, each up to 1MB"]', rw_rejection_reasons='["Needing a listing inside six months on free, anything outside their AI/productivity categories, and rejection on limited free slots"]', rw_gotchas='["Their own free card puts the queue over 180 days at current pace — longer than most makers will wait and longer than most directories admit.","The same card says a free submission may be rejected for limited slots, so the wait does not guarantee a listing at the end.","The step is called Payment and the free option is the third card, under the two that cost money.","An AI Autofill button offers to write your listing from your URL — a fast way to publish copy nobody at your company wrote."]', rw_faq='[{"question":"How long does FeaturedTool approval take?","answer":"Free queue is over 180 days at current pace; the card itself admits this."},{"question":"How much does it cost to submit to FeaturedTool?","answer":"Free with three dofollow links and a 180-day-plus queue; $9.90 publishes immediately with no badge; $19.90 adds seven days at the top."},{"question":"Does a FeaturedTool listing provide a dofollow link?","answer":"Yes, three dofollow links on a domain rated 38."},{"question":"Do I need to link back to FeaturedTool?","answer":"No backlink is required on any tier."},{"question":"What gets a listing rejected?","answer":"Needing a fast listing, being outside their categories, or losing a limited free slot."}]', rw_summary='FeaturedTool is a free dofollow directory with an honest 180-day-plus queue and no required backlink. Domain rating is 38.', rw_fact_points='["Free queue over 180 days","Free listing with three dofollow links","No required backlink","Accepts AI and productivity tools"]', rw_submission_checks='["Expect a six-month-plus wait on free.","Free slots can still be rejected.","AI Autofill writes the listing from your URL."]', rw_seo_title='FeaturedTool: Free Queue Listing, DR 38', rw_seo_description='How to submit to FeaturedTool: free dofollow listing with an honest 180-day queue, no backlink. Rules from the 2026-11-16 snapshot.' WHERE slug='featuredtool';
UPDATE submission_sites SET rw_source_lead='Eighty dollars is the floor here, and that figure is already the sale price.', rw_what_you_get='A dofollow listing with no backlink, from $79.99 once with a verified badge sold separately.', rw_you_need='["An account, or the payment flow that creates one","A payment — the cheapest listing is $79.99"]', rw_eligibility='You need to pay. There is no free submission of any kind.', rw_submit_steps='["1 Pick a plan. Three tiers on the submit page, each with a struck-through price beside a sale price; a verified badge is a $9.99 add-on.","2 Account. The page carries sign-in and sign-up forms alongside the plans, so the account and payment are one step.","3 Submit. Tools and AI agents are separate flows with separate forms — pick the right one."]', rw_submit_requirements='["A payment from $79.99 before any listing detail","An account email and password created in the same flow","A verified badge optional at $9.99 extra"]', rw_rejection_reasons='["Unwillingness to pay — there is no free submission of any kind"]', rw_gotchas='["The sale banner is baked into the page title all year, so the deadline it implies is not one.","The verified badge is a separate $9.99 on two of three tiers, so the advertised price is not the price of the listing most people picture.","Tools and agents are two submissions with two forms; picking the wrong one means starting again."]', rw_faq='[{"question":"How long does FindMyAITool.com approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to FindMyAITool.com?","answer":"$79.99 Basic (from $99.99), $99.99 Featured (from $149.99), $149.99 Standard (from $199.99), all one-time. Verified badge $9.99 on two tiers. No free lane."},{"question":"Does a FindMyAITool.com listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 37."},{"question":"Do I need to link back to FindMyAITool.com?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Unwillingness to pay."}]', rw_summary='FindMyAITool.com is a paid-only $79.99+ dofollow directory with no backlink, where a verified badge costs extra. Domain rating is 37.', rw_fact_points='["No published review time","Paid-only from $79.99, dofollow","No badge or return link is expected","Accepts AI tools and agents"]', rw_submission_checks='["The sale price is permanent.","The verified badge is $9.99 extra.","Tools and agents use different forms."]', rw_seo_title='FindMyAITool.com: $79.99 Dofollow, DR 37', rw_seo_description='How to submit to FindMyAITool.com: $79.99+ one-time dofollow listing, no backlink. Paid-only from the 2026-11-16 snapshot.' WHERE slug='findmyaitool-com';
UPDATE submission_sites SET rw_source_lead='A badge-first directory of new AI tools and launches, where the free listing is the only listing.', rw_what_you_get='A dofollow listing gated behind a live badge check on your nominated page.', rw_you_need='["An account via Google or email","Their badge checked live before the form appears","An uploaded screenshot and square icon and a description up to 150 characters"]', rw_eligibility='You need an account, a reachable site and a badge. Anyone who cannot host the badge, or whose page the crawler cannot reach, is out.', rw_submit_steps='["1 Sign in with Google or an email account created with them.","2 Add your website — the product homepage, from which the badge and listing slug are generated.","3 Badge and verify. Light and dark snippets point at your listing; name the page to fetch and press Verify Badge to open step three.","4 Details: a site name, screenshot, icon, up to four categories, a pricing model, a 150-character short description and a 1,500-character overview, then terms and Submit for Review."]', rw_submit_requirements='["An account and their live-verified 238x54 PNG badge","A site name and a screenshot up to 10MB","A square icon up to 5MB and up to four categories","A pricing model, a 150-character summary and a 1,500-character overview"]', rw_rejection_reasons='["A site that cannot carry the badge, or one the crawler cannot reach"]', rw_gotchas='["The whole form sits behind the badge check — step three does not exist until the crawler finds it.","Their snippet asks for a do-follow link to your listing URL, stricter than usual, so a site that nofollows footer links must make an exception.","No review window is published — the success page only says the tool is under review.","The success page cross-offers a grid of sister directories from the same operator."]', rw_faq='[{"question":"How long does Latest AI Updates approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Latest AI Updates?","answer":"Submitting is free with a badge."},{"question":"Does a Latest AI Updates listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 38."},{"question":"Do I need to link back to Latest AI Updates?","answer":"Yes — a badge is required."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry the badge or that the crawler cannot reach."}]', rw_summary='Latest AI Updates is a free dofollow AI-launch directory with a live badge gate and no other backlink. Domain rating is 38.', rw_fact_points='["No published review time","Free listing with a dofollow link","A live badge gates the form","Accepts new AI tools and launches"]', rw_submission_checks='["Install the badge before the form appears.","Make it dofollow to the reserved URL.","Reach overlaps with sister directories."]', rw_seo_title='Latest AI Updates: Free Badge Listing, DR 38', rw_seo_description='How to submit to Latest AI Updates: free dofollow AI listing gated on a live badge. Rules from the 2026-11-16 snapshot.' WHERE slug='latestaiupdates';
