UPDATE submission_sites SET rw_source_lead='A badge-first AI tools directory built around comparison, where the free listing is the only listing.', rw_what_you_get='A dofollow listing gated behind a live badge check on your nominated page.', rw_you_need='["An account via Google or email","Their badge checked live before the form appears","An uploaded screenshot and square icon and a description up to 150 characters"]', rw_eligibility='You need an account, a reachable site and a badge. Anyone who cannot host the badge, or whose page the crawler cannot reach, is out.', rw_submit_steps='["1 Sign in with Google or an email account created with them.","2 Add your website — the product homepage, from which the badge and listing slug are generated.","3 Badge and verify. Light and dark snippets point at your listing; name the page to fetch and press Verify Badge to open step three.","4 Details: a site name, screenshot, icon, up to four categories, a pricing model, a 150-character short description and a 1,500-character overview, then terms and Submit for Review."]', rw_submit_requirements='["An account and their live-verified 176x54 PNG badge","A site name and a screenshot up to 10MB","A square icon up to 5MB and up to four categories","A pricing model, a 150-character summary and a 1,500-character overview"]', rw_rejection_reasons='["A site that cannot carry the badge, or one the crawler cannot reach"]', rw_gotchas='["The whole form sits behind the badge check — step three does not exist until the crawler finds it.","Their snippet asks for a do-follow link to your listing URL, stricter than usual, so a site that nofollows footer links must make an exception.","No review window is published — the success page only says the tool is under review.","The success page cross-offers a grid of sister directories from the same operator."]', rw_faq='[{"question":"How long does Tool Prism approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Tool Prism?","answer":"Submitting is free with a badge."},{"question":"Does a Tool Prism listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 38."},{"question":"Do I need to link back to Tool Prism?","answer":"Yes — a badge is required."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry the badge or that the crawler cannot reach."}]', rw_summary='Tool Prism is a free dofollow comparison-based AI directory with a live badge gate and no other backlink. Domain rating is 38.', rw_fact_points='["No published review time","Free listing with a dofollow link","A live badge gates the form","Accepts AI tools for comparison"]', rw_submission_checks='["Install the badge before the form appears.","Make it dofollow to the reserved URL.","Reach overlaps with sister directories."]', rw_seo_title='Tool Prism: Free Badge Listing, DR 38', rw_seo_description='How to submit to Tool Prism: free dofollow AI listing gated on a live badge. Rules from the 2026-11-16 snapshot.' WHERE slug='toolprism';
UPDATE submission_sites SET rw_source_lead='$2.90 for three dofollow links in 72 hours, and only the $9.90 tier says no backlink required.', rw_what_you_get='Three dofollow links from $2.90 once, with the cheaper tier expecting backlink maintenance.', rw_you_need='["A live product URL and $2.90"]', rw_eligibility='You need to pay and a live product. Nothing is published as a refusal rule.', rw_submit_steps='["1 Pick a tier. Basic $2.90 buys three dofollow links, permanent with backlink maintenance, reviewed within 72 hours, published on a chosen day, with no support. Pro $9.90 lists immediately, needs no backlink and adds featured treatment and social sharing.","2 Pay, then submit. Both tiers route through a payment page; the form sits behind payment.","3 Choose a publish date. Both tiers let you pick the day the listing goes live."]', rw_submit_requirements='["A payment from $2.90","A product name, description and URL and a category"]', rw_rejection_reasons='["Nothing published"]', rw_gotchas='["Read the two tiers side by side — only Pro says no backlink required, implying Basic expects one; their FAQ addresses exactly that.","Basic explicitly includes no customer support, so at that price you are on your own.","Sponsorship is $19.90 a week and recurring, unlike the one-time listing tiers."]', rw_faq='[{"question":"How long does UtilPortal approval take?","answer":"Three to five days; Basic promises review within 72 hours."},{"question":"How much does it cost to submit to UtilPortal?","answer":"$2.90 Basic with backlink maintenance and no support; $9.90 Pro lists immediately with no backlink and featured treatment; $19.90 a week to sponsor."},{"question":"Does a UtilPortal listing provide a dofollow link?","answer":"Yes, three dofollow links on a domain rated 37."},{"question":"Do I need to link back to UtilPortal?","answer":"No required backlink, though the $2.90 tier expects backlink maintenance."},{"question":"What gets a listing rejected?","answer":"Nothing published."}]', rw_summary='UtilPortal is a paid $2.90+ dofollow directory with three links and no required backlink, where the cheap tier expects link maintenance. Domain rating is 37.', rw_fact_points='["72-hour Basic review","Paid-only from $2.90, three dofollow links","No required backlink; Basic expects maintenance","Accepts SaaS, AI tools and dev tools"]', rw_submission_checks='["Only Pro explicitly needs no backlink.","Basic has no customer support.","Sponsorship recurs weekly."]', rw_seo_title='UtilPortal: $2.90 Dofollow Listing, DR 37', rw_seo_description='How to submit to UtilPortal: $2.90+ one-time for three dofollow links. Backlink nuance from the 2026-11-16 snapshot.' WHERE slug='utilportal';
UPDATE submission_sites SET rw_source_lead='A curated directory whose free tier gives three followed links and says in the same card the queue is 180 days and a slot may be refused.', rw_what_you_get='Three dofollow links on free with a permanent listing, if you accept a stated 180-day queue and possible refusal.', rw_you_need='["An account via Google or GitHub","An uploaded logo and screenshot","Patience, or $9.90"]', rw_eligibility='You need an account and media. Anyone needing a listing this year on free, or unable to absorb a refusal for limited slots, is out.', rw_submit_steps='["1 Sign in with Google or GitHub at the auth route — no email-and-password option.","2 Enter product details: a link, name, categories, tags, a short description, a Markdown introduction and two image uploads. An AI Autofill button offers to write it from your URL.","3 Choose a plan — Free, Listing $9.90 or Featured $19.90. The details step must be sent before plans appear.","4 Submit to review. The free card''s button reads Submit to review and becomes Go dashboard and Wait afterward."]', rw_submit_requirements='["An account and a product name and link","Categories and tags and a one-line description","A Markdown introduction and both a logo and screenshot upload"]', rw_rejection_reasons='["Needing a listing this year on free, with a stated 180-day queue, or losing one of the limited free slots"]', rw_gotchas='["The free card states a 180-day wait at current pace and says a submission may be rejected for limited slots — more honest than most and worth reading first.","Free gets exactly three followed links and the paid tiers get three or more, so $9.90 buys immediacy, not link count.","An AI Autofill button offers to write the whole listing from your URL — a fast way to publish copy nobody wrote.","Tags are a searchable list that is not exhaustive: there is no Directory tag, so a directory must file under something else."]', rw_faq='[{"question":"How long does 600.tools approval take?","answer":"Six months or more; the free card states a 180-day queue."},{"question":"How much does it cost to submit to 600.tools?","answer":"Free with three dofollow links and a 180-day queue; $9.90 publishes immediately with no backlink; $19.90 adds seven days at the top."},{"question":"Does a 600.tools listing provide a dofollow link?","answer":"Yes, three dofollow links on a domain rated 36."},{"question":"Do I need to link back to 600.tools?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"The free queue, a limited slot, or nothing else published."}]', rw_summary='600.tools is a free dofollow curated directory giving three links, but with an honest 180-day queue and no required backlink. Domain rating is 36.', rw_fact_points='["Free queue over 180 days","Free listing with three dofollow links","No required backlink","Accepts SaaS, dev tools and AI tools"]', rw_submission_checks='["Expect a six-month wait on free.","Free slots can be refused.","The tag list has gaps."]', rw_seo_title='600.tools: Free Queue Listing, DR 36', rw_seo_description='How to submit to 600.tools: free three-link dofollow listing with an honest 180-day queue. No backlink — 2026-11-16 snapshot.' WHERE slug='600-tools';
UPDATE submission_sites SET rw_source_lead='A Yahoo-era general web directory with 440 categories and a free permanent listing whose outbound link carries no rel at all.', rw_what_you_get='A permanent dofollow listing in a general directory, free with a captcha or $15.95 for a higher position.', rw_you_need='["A finished site and a carefully written description"]', rw_eligibility='You need a complete site and clean copy. Affiliate-heavy sites, mirrors, redirects, under-construction pages and pornography are refused by name.', rw_submit_steps='["1 Read the rules. The add-URL page opens with them: no affiliate sites, mirrors, redirect pages, under construction or pornography.","2 Pick a tier. Premium Links at $15.95 or Regular free — Premium is preselected.","3 Fill the form: one of 440 categories, a URL, title, description, your name and email. No account.","4 Confirm. A review screen prints everything back, then asks for a code from a distorted image before Submit."]', rw_submit_requirements='["A direct website URL, not a redirect","A title and a carefully written description","One of 440 categories and your name and email","An optional $15.95 fee"]', rw_rejection_reasons='["Affiliate programmes and mostly-affiliate sites, mirrors, redirect pages and pornography — all refused by name"]', rw_gotchas='["The paid tier is preselected, so filling straight down the page is a $15.95 submission; free is the second radio and must be chosen deliberately.","An image captcha sits on the confirmation screen after everything else is filled, so the last click needs a person.","They say errors or bad grammar in the description delay approval, and no review window is published."]', rw_faq='[{"question":"How long does 9Sites.net approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to 9Sites.net?","answer":"Regular Links free and permanent; Premium Links $15.95 once sit above the free ones. The fee buys position, not the listing."},{"question":"Does a 9Sites.net listing provide a dofollow link?","answer":"Yes — the outbound link carries no rel attribute on a domain rated 35."},{"question":"Do I need to link back to 9Sites.net?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"Affiliate-heavy sites, mirrors, redirects, under-construction pages and pornography."}]', rw_summary='9Sites.net is a free permanent dofollow general directory with no backlink, 440 categories and a captcha at the end. Domain rating is 35.', rw_fact_points='["No published review time","Free listing with a dofollow link","No required backlink","Accepts any finished website"]', rw_submission_checks='["The paid tier is preselected — choose free.","A person must solve the captcha.","Write the description carefully."]', rw_seo_title='9Sites.net: Free Web Listing, DR 35', rw_seo_description='How to submit to 9Sites.net: free permanent dofollow web listing, no backlink. 440 categories and a captcha — 2026-11-16 snapshot.' WHERE slug='9sites';
UPDATE submission_sites SET rw_source_lead='An AI agent directory offering a free listing and a followed link, whose social sign-in never finishes loading.', rw_what_you_get='A free dofollow agent listing with no backlink — if you can get past a password-only account.', rw_you_need='["An account, and in practice a username and password","A product that reads as an AI agent or tool"]', rw_eligibility='You need to create a password account. Anyone who will not, or anything outside AI agents and tools, is out.', rw_submit_steps='["1 Read the pitch. The submit-your-tool page sells the free listing, followed link and 82 categories; its button goes to registration, not a form.","2 Make an account with a username, email, full name and a password under four stated rules.","3 Fill the listing behind the account — its fields are not visible beforehand."]', rw_submit_requirements='["A username and password account in practice","A product name and URL behind the account","A category from 82 offered"]', rw_rejection_reasons='["Refusing a password account, since social sign-in is broken, and anything outside AI agents and tools"]', rw_gotchas='["Social sign-in is broken: Google, X, GitHub and Apple all sit at Loading sign-in indefinitely across fresh loads, with nothing in the console.","That leaves a password account as the only way in, enforced with four separate password rules.","The Submit button goes straight to registration, so nothing about the listing form can be read before making an account.","The login page offers four social providers that registration does not, so a visitor following the obvious route never sees the advertised option."]', rw_faq='[{"question":"How long does AgentLocker approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to AgentLocker?","answer":"The listing is free and their pitch says under five minutes; a separate See Featured Options route sells paid placement."},{"question":"Does an AgentLocker listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 35."},{"question":"Do I need to link back to AgentLocker?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Refusing a password account or being outside AI agents and tools."}]', rw_summary='AgentLocker is a free dofollow AI-agent directory with no backlink, but its social sign-in is broken so a password account is mandatory. DR 35.', rw_fact_points='["No published review time","Free listing with a dofollow link","No badge or return link is expected","Accepts AI agents and tools"]', rw_submission_checks='["Social sign-in does not work — use a password.","The form is hidden behind registration.","Four password rules apply."]', rw_seo_title='AgentLocker: Free Agent Listing, DR 35', rw_seo_description='How to submit to AgentLocker: free dofollow agent listing, no backlink. Broken sign-in from the 2026-11-16 snapshot.' WHERE slug='agentlocker';
UPDATE submission_sites SET rw_source_lead='An AI agent directory behind a checkpoint, whose free tier swaps a followed link for a link back and reviews inside 72 hours.', rw_what_you_get='A dofollow listing that costs a link back on free, reviewed within 72 hours.', rw_you_need='["An account via Google, GitHub or email","A link back to them on your site unless you pay $5.99","An uploaded logo and screenshot"]', rw_eligibility='You need an account, a linkable site and an agent-adjacent product. Anyone who cannot add a link, or whose tool is not recognisably an agent, is out.', rw_submit_steps='["1 Get past the checkpoint. A security check guards the site and takes about twenty seconds on first visit.","2 Sign in with Google, GitHub or email and password from the submit route.","3 Enter the details: a link, name, categories, tags, a short description, a Markdown introduction and two image uploads. An AI Autofill button can write it from your URL.","4 Choose a plan: free with a link back, or Pro $5.99 without one. Free sends it to backlink verification.","5 Verify the backlink. A badge or plain text link points at your listing; paste one on your site, name the page and press Verify Backlink."]', rw_submit_requirements='["An account and a badge or text link on a page you name","A product name and link and a one-line description","Categories and tags and a Markdown introduction","A logo and screenshot upload"]', rw_rejection_reasons='["A site that cannot carry a link back, and anything not recognisably an AI agent or agent-adjacent tool"]', rw_gotchas='["A checkpoint guards every page and can answer 429 to a first request, which reads as downtime when it is a twenty-second wait.","The free tier holds the listing at Verifying Backlink until the checker finds your link, and it asks for the exact page rather than checking your homepage.","The badge is an inline SVG with no image file to vendor; a plain text link is the alternative.","An AI Autofill button can write the whole listing from your URL — a fast way to publish copy nobody wrote."]', rw_faq='[{"question":"How long does AgentWise approval take?","answer":"One to two days; free review is inside 72 hours."},{"question":"How much does it cost to submit to AgentWise?","answer":"Free with a link back, reviewed in 72 hours. Pro $5.99 once drops the link, publishes instantly with featured placement and social promotion."},{"question":"Does an AgentWise listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 36."},{"question":"Do I need to link back to AgentWise?","answer":"Yes on free — a badge or text link is required."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry a link, or a tool that is not agent-adjacent."}]', rw_summary='AgentWise is a free dofollow AI-agent directory priced on free with a link back and a 72-hour review. No other backlink; domain rating is 36.', rw_fact_points='["Review inside 72 hours","Free listing with a dofollow link","A link back is required on free","Accepts AI agents and agent tools"]', rw_submission_checks='["The checkpoint may return 429 first.","Name the exact page carrying the link.","$5.99 drops the link requirement."]', rw_seo_title='AgentWise: Free Link-Back Listing, DR 36', rw_seo_description='How to submit to AgentWise: free dofollow agent listing for a link back, 72-hour review. Checkpoint from the 2026-11-16 snapshot.' WHERE slug='agentwise';
UPDATE submission_sites SET rw_source_lead='An AI tools directory charging $44.99 for a listing whose outbound link is nofollow and routed through a redirect to an affiliate URL.', rw_what_you_get='A nofollow listing behind a redirect into an affiliate URL, for $44.99 once — buy it for visibility, not link value.', rw_you_need='["$44.99 — there is no other route","A product that reads as an AI tool"]', rw_eligibility='You need to pay and an AI tool. Anyone submitting for the backlink, or on a zero budget, is out.', rw_submit_steps='["1 Pick a package: Basic $44.99 or Featured $89.99, both one-time with no free option.","2 Pay. The package buttons lead into payment before listing details are collected.","3 Wait for listing. Basic states 48 hours and a day or two as a new tool on the homepage."]', rw_submit_requirements='["A $44.99 one-time payment, no free tier","A product name and URL and a category from their list"]', rw_rejection_reasons='["Submitting for the backlink, since the link is nofollow and redirected, and anyone on a zero budget"]', rw_gotchas='["The listing link is nofollow and does not point at your site — the button targets their own go path, which redirects onward.","That redirect lands on an affiliate URL where the tool runs a programme, so the click is monetised and the destination is not your plain homepage."]', rw_faq='[{"question":"How long does AI Tools One approval take?","answer":"One to two days; Basic states 48 hours."},{"question":"How much does it cost to submit to AI Tools One?","answer":"Basic $44.99 once for a permanent listing within 48 hours; Featured $89.99 adds seven days featured and the top category spot. No free tier."},{"question":"Does an AI Tools One listing provide a dofollow link?","answer":"No — links are nofollow and route through an affiliate redirect on a domain rated 35."},{"question":"Do I need to link back to AI Tools One?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Submitting for link value, or having no budget."}]', rw_summary='AI Tools One is a paid-only $44.99 nofollow AI directory with no backlink, where the outbound link redirects to an affiliate URL. DR 35.', rw_fact_points='["48-hour Basic listing","Paid-only from $44.99, nofollow","No badge or return link is expected","Accepts AI tools and SaaS"]', rw_submission_checks='["The link is nofollow and redirected.","It may land on an affiliate URL.","No free tier exists."]', rw_seo_title='AI Tools One: $44.99 Nofollow Listing, DR 35', rw_seo_description='How to submit to AI Tools One: $44.99 one-time nofollow listing, no backlink. Affiliate redirect from the 2026-11-16 snapshot.' WHERE slug='aitoolsone';
UPDATE submission_sites SET rw_source_lead='A dev-tools launch board whose free lane pays a followed link for a badge, against a stated sixty-day queue — but whose badge checkbox is broken.', rw_what_you_get='A dofollow listing for a badge in theory, but the free lane currently cannot be completed because the confirmation checkbox does not respond.', rw_you_need='["An account via Google, GitHub or email","Their badge on your site before the form will let you finish","An uploaded logo and wide product image"]', rw_eligibility='You need an account, media and a working badge flow. At snapshot time the badge checkbox defect blocked everyone on free, and a listing inside two months is impossible against the stated queue.', rw_submit_steps='["1 Sign in with Google, GitHub or email and password.","2 Project Info: a name, website URL, optional affiliate URL, a rich-text short description, then a logo and product image as uploads.","3 Details: up to three searchable categories, up to five tech tags, platforms, pricing and optional GitHub and Twitter URLs.","4 Launch Type and badge. Free Launch shows the badge snippet, a checkbox and Verify Backlink; Next stays disabled until it passes.","5 Review and submit. A summary, then Submit Project."]', rw_submit_requirements='["An account and their 150x44 SVG badge verified live","A product name and rich-text short description","A 1:1 logo upload and up to three categories","Up to five tech tags and an optional wide product image"]', rw_rejection_reasons='["At snapshot time everyone on free — the badge confirmation checkbox does not respond — and anyone needing a listing inside two months"]', rw_gotchas='["The badge checkbox does not respond: clicking the box, label and hidden input all leave it unchecked, so Verify Backlink stays disabled and the free lane cannot be finished even with the badge live.","The badge must be live before that step would let you through, but the snippet points at a listing page that does not exist until the first two steps are filled, so it cannot be put up in advance.","Sixty days is the stated free queue, longer than sibling boards on the same software, so the same badge buys a slower listing here.","An AI Autofill button can write the whole listing from your URL — a fast way to publish copy nobody wrote."]', rw_faq='[{"question":"How long does DevHub approval take?","answer":"Two to three months; the free card states up to 60 days."},{"question":"How much does it cost to submit to DevHub?","answer":"Free Launch is $0 for a badge and a followed link within 60 days. Premium $9.90 skips the queue with five slots a day; higher tiers and a ten-site DR Booster are sold separately."},{"question":"Does a DevHub listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 36, if the free lane can be completed."},{"question":"Do I need to link back to DevHub?","answer":"Yes — a badge is required on free."},{"question":"What gets a listing rejected?","answer":"Currently everyone on free — the checkbox defect — and anyone needing a fast listing."}]', rw_summary='DevHub is a dofollow dev-tool launch board with a 60-day free queue and a required badge, but its badge checkbox was broken at snapshot. Domain rating is 36.', rw_fact_points='["Free queue up to 60 days","Dofollow link gated on a badge","Badge required on free","Accepts dev tools, SaaS and AI tools"]', rw_submission_checks='["The badge checkbox does not respond — free cannot be finished.","The badge URL does not exist until steps one and two.","Sixty days is longer than sibling boards."]', rw_seo_title='DevHub: Free Badge Launch, DR 36', rw_seo_description='How to submit to DevHub: dofollow dev-tool listing for a badge, 60-day queue. Broken checkbox from the 2026-11-16 snapshot.' WHERE slug='devhub';
UPDATE submission_sites SET rw_source_lead='A permanent dofollow listing for free if their badge stays on your site, or $29.99 to skip the badge and get the newsletter and X post.', rw_what_you_get='A permanent dofollow listing rented against a badge, or $29.99 once to drop the badge and add promotion.', rw_you_need='["An account and a live product","Their badge embedded on the free tier"]', rw_eligibility='You need an account, a live product and — on free — a badge. Nothing is published as a refusal rule.', rw_submit_steps='["1 Create an account. Signup offers Google sign-up; a cookie notice sits over the page first with a Decline.","2 Fill the whole listing before any plan question: app name and URL, a landing-page heading and sub-heading, creator name, one image and one of fifteen categories.","3 Meet the plan modal on Submit. Free is labelled Badge Required; Pro is $29.99 once from $54. SUBMIT FREE APP takes the badge lane.","4 Embed the badge and validate. Next.js and HTML snippets wrap the same anchor; Validate Badge checks your site live and publishes on a pass."]', rw_submit_requirements='["An account and an app name and URL","A landing-page heading and sub-heading and a creator name","One image, ideally a wide landing hero, and one of fifteen categories","Their badge on your site for free, or $29.99"]', rw_rejection_reasons='["Nothing published"]', rw_gotchas='["Categories is plural but single-select — exactly one of fifteen fixed options including AI, Agent, Seo, Design and Notion-Alternatives.","The image slot asks for a landing hero, not an icon, so a square logo renders letterboxed on your card.","Both plan cards print Secure 256-bit Stripe Checkout underneath, including free — but the free lane never opens Stripe, it goes straight to the badge step."]', rw_faq='[{"question":"How long does IndieTool approval take?","answer":"Instant — publication follows badge validation."},{"question":"How much does it cost to submit to IndieTool?","answer":"Free with a badge. $29.99 once, down from $54, drops the badge and adds featuring, a newsletter send and an X post."},{"question":"Does an IndieTool listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 35 while the badge stays live."},{"question":"Do I need to link back to IndieTool?","answer":"Yes — a badge is required on free."},{"question":"What gets a listing rejected?","answer":"Nothing published."}]', rw_summary='IndieTool is a free dofollow indie-product directory where a permanent badge rents the link, or $29.99 drops it and adds promotion. DR 35.', rw_fact_points='["Instant publication on badge validation","Free listing with a dofollow link","A badge is required on free","Accepts indie products and SaaS"]', rw_submission_checks='["Only one category of fifteen.","The image should be a wide hero.","Free never opens Stripe despite the label."]', rw_seo_title='IndieTool: Free Badge Listing, DR 35', rw_seo_description='How to submit to IndieTool: free dofollow listing for a badge, or $29.99 to drop it. Rules from the 2026-11-16 snapshot.' WHERE slug='indietool';
UPDATE submission_sites SET rw_source_lead='A free three-step launch into a weekly competition and a 50,000-reader digest, with ugc nofollow on every listing.', rw_what_you_get='A nofollow launch entry whose value is a weekly contest and a large digest, not link equity.', rw_you_need='["A live URL their fetcher can read","An account to finish the launch"]', rw_eligibility='You need a readable live URL and an account. Nothing is published as a refusal rule.', rw_submit_steps='["1 Give them the URL. Step one of three is the website URL alone; they fetch the title, description and logo from the page.","2 Check the details. Step two is the generated detail — replace whatever the fetch produced with your own copy.","3 Launch. Step three schedules it; launches run weekly with prizes for the top three and winners archived."]', rw_submit_requirements='["A live product URL and an account","Your own title, description and logo to replace the fetched ones, optional"]', rw_rejection_reasons='["Nothing published"]', rw_gotchas='["Every outbound link on a live listing carries rel=ugc nofollow noopener noreferrer, so nothing passes to your domain whatever the placement.","Their copy leads on a 50,000-subscriber weekly digest and top-three prizes — the value is the audience, not SEO.","They also sell their own directory-submission service, so read their advice about submitting elsewhere with that in mind."]', rw_faq='[{"question":"How long does Just Hunt approval take?","answer":"About a week, into the weekly launch."},{"question":"How much does it cost to submit to Just Hunt?","answer":"Submitting is free."},{"question":"Does a Just Hunt listing provide a dofollow link?","answer":"No — all listing links are ugc nofollow on a domain rated 35."},{"question":"Do I need to link back to Just Hunt?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published."}]', rw_summary='Just Hunt is a free nofollow weekly launch contest with no backlink, pitched on a large digest rather than SEO. Domain rating is 35.', rw_fact_points='["Weekly launch about a week out","Free listing with ugc nofollow links","No badge or return link is expected","Accepts indie products, SaaS and AI tools"]', rw_submission_checks='["The link passes nothing — the value is the audience.","Replace the fetched copy.","They sell their own submission service."]', rw_seo_title='Just Hunt: Free Weekly Launch, DR 35', rw_seo_description='How to launch on Just Hunt: free nofollow weekly contest, no backlink. Digest value from the 2026-11-16 snapshot.' WHERE slug='justhunt';
UPDATE submission_sites SET rw_source_lead='A weekly startup league that resets every Monday, where the badge, a real profile and supporting other founders are all gates before you can enter.', rw_what_you_get='A dofollow entry in a weekly league, gated on a permanent badge, a completed founder profile and weekly support of other makers.', rw_you_need='["A Google account — the only sign-in","A completed founder profile with name and bio","Their dofollow badge on your homepage, two upvotes and two site visits each week","A square logo and a 16:9 cover"]', rw_eligibility='You need to do the weekly chores and carry the badge. A product whose homepage lacks the badge at entry time is refused.', rw_submit_steps='["1 Sign in with Google — there is no email option.","2 Complete your founder profile first: a first name, last name and bio are required, and upvotes silently do nothing until it is saved.","3 Draft the product: a name up to 20, a tagline up to 80, a URL, a square logo of at least 200x200 up to 2MB and a 16:9 cover up to 3MB.","4 Put their badge up. The snippet carries a product slug filled in only after you type the name; their crawler checks at submission and again at launch.","5 Support two founders — two upvotes and two creator-site visits, with Visit buttons appearing only on hover.","6 Save, then enter the gameweek. Saving only drafts it as Not Entered; Schedule Launch and Enter Gameweek are separate clicks."]', rw_submit_requirements='["A Google account and a completed founder profile","A live URL, a name up to 20 and a tagline up to 80","A square logo and a 16:9 cover","Their badge on your homepage and two upvotes plus two visits per week"]', rw_rejection_reasons='["A product whose homepage does not carry the badge at entry time"]', rw_gotchas='["Google-only sign-in ties the listing to a Google identity — set the profile name deliberately, it becomes your public byline.","Upvotes silently fail until the founder profile has a name and bio saved; the counter just stays at 0 of 2.","The badge snippet contains a your-product placeholder until you type the name — copy it too early and you deploy a badge pointing nowhere.","Saving does not enter the product — the dashboard shows Not Entered until Schedule Launch and Enter Gameweek are clicked.","Quest counters do not live-update and Refresh did not help; only a full reload showed them, which loses everything typed.","Entries are for the upcoming week only, and a top-20 finish forces a one-week cooling-off."]', rw_faq='[{"question":"How long does Launch League approval take?","answer":"About a week, into the next Monday gameweek."},{"question":"How much does it cost to submit to Launch League?","answer":"Submitting is free with the badge and weekly chores."},{"question":"Does a Launch League listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 36 while the badge is live."},{"question":"Do I need to link back to Launch League?","answer":"Yes — a dofollow badge is checked at entry and at launch."},{"question":"What gets a listing rejected?","answer":"A homepage without the badge at entry time."}]', rw_summary='Launch League is a free dofollow weekly startup league gated on a badge, a real profile and weekly chores. No other backlink; DR 36.', rw_fact_points='["Weekly Monday gameweek","Free listing with a dofollow link","Badge plus chores required","Accepts startups, SaaS and AI tools"]', rw_submission_checks='["Upvotes fail until the profile is saved.","Fill the name before copying the badge.","Save is not entry — enter the gameweek."]', rw_seo_title='Launch League: Free Weekly League, DR 36', rw_seo_description='How to launch on Launch League: free dofollow weekly league gated on a badge and chores. Quirks from the 2026-11-16 snapshot.' WHERE slug='launchleague';
UPDATE submission_sites SET rw_source_lead='A weekly board where winning is free but the link only lasts while their badge is on your site, and $11 buys you out of the queue and the badge.', rw_what_you_get='A dofollow listing rented against a badge on free, or $11 once for a permanent link with no badge and no queue.', rw_you_need='["An account via Google and a live product","Their badge on your site on the free tier"]', rw_eligibility='You need an account and a live product. Nothing is published as a refusal rule.', rw_submit_steps='["1 Sign in with Google and fill the product: a website, name, tagline up to 70, description up to 600, a square logo, up to four screenshots, one of fourteen categories and an optional pinned maker comment.","2 Choose how you launch. Premium $11 is preselected; Standard is $0 and takes the next week with free capacity, with the current week usually full.","3 Decline the upsell. Choosing Standard opens a dialog offering to launch a week sooner for $11; Continue free is the small link under the two paid buttons.","4 Verify the badge to go live. A free-only third step shows the per-product SVG badge with a dofollow link; Verify and publish puts the page up and books your week."]', rw_submit_requirements='["A Google account and a product name, website, tagline up to 70 and description up to 600","A square logo and one of fourteen categories","Their badge on your site for free","Up to four screenshots and a maker comment optional","$11 to skip the queue and badge optional"]', rw_rejection_reasons='["Nothing published"]', rw_gotchas='["The free backlink is rented, not owned — it lasts while the badge is live; take the badge down and the link goes. The $11 tier explicitly needs no badge.","The page publishes as soon as the badge verifies, but the board slot is a future week, so being live and being seen are different dates.","The maker comment typed during submission does not survive the flow — add it afterwards from the product edit page, where it saves fine."]', rw_faq='[{"question":"How long does NoonLaunch approval take?","answer":"Instant to publish; the board slot is the next week with free capacity."},{"question":"How much does it cost to submit to NoonLaunch?","answer":"Free with a badge and a weekly wait; $11 once per product skips the queue, drops the badge and adds a permanent directory listing."},{"question":"Does a NoonLaunch listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 35 while the badge is live."},{"question":"Do I need to link back to NoonLaunch?","answer":"Yes on free — the link is rented against the badge."},{"question":"What gets a listing rejected?","answer":"Nothing published."}]', rw_summary='NoonLaunch is a free dofollow weekly launch board where the link is rented against a badge, or $11 makes it permanent. DR 35.', rw_fact_points='["Instant publish, next-week board slot","Free listing with a rented dofollow link","A badge is required on free","Accepts indie products, SaaS and AI tools"]', rw_submission_checks='["The free link lasts only while the badge is live.","Live date and board date differ.","Add the maker comment after submit."]', rw_seo_title='NoonLaunch: Free Weekly Launch, DR 35', rw_seo_description='How to launch on NoonLaunch: free dofollow listing with a rented badge link, or $11 permanent. Rules from the 2026-11-16 snapshot.' WHERE slug='noonlaunch';
UPDATE submission_sites SET rw_source_lead='A university-affiliated research database of 63,000 AI tools, free to be added to, that ranks what it tracks and links out to none of it.', rw_what_you_get='A place in a research ranking with no backlink at all — tool names are printed as plain text with no anchor.', rw_you_need='["A dedicated website or subdomain, which the form states as a rule","A significant AI component and a legal company name"]', rw_eligibility='You need a dedicated domain or subdomain, a real AI component and a legal company name. Anything hosted on a shared path, or without meaningful AI, is refused.', rw_submit_steps='["1 Open the form. It takes the whole submission — no account, no payment, nothing to sign in to.","2 Fill three blocks: your name and email, the tool (name, URL, use cases in 300 characters, a 400-character description, optional Product Hunt link), then the company, where the legal name is required.","3 Answer the last three: pricing as one word in 15 characters, a pricing page URL, and API availability as yes or no.","4 Send. One button, no captcha; the form clears and prints no confirmation."]', rw_submit_requirements='["Your name and email and a tool name and URL on its own domain or subdomain","Use cases up to 300 and a description up to 400 characters","A legal company name, pricing in one word and API yes or no","An optional Product Hunt link and company details"]', rw_rejection_reasons='["Anything without a meaningful AI component, and anything hosted on a shared path rather than its own domain or subdomain"]', rw_gotchas='["Nothing here links out — rankings print tool names as plain text with no anchor, so a place in the database is exposure and never a backlink.","The form requires a legal company name alongside optional address, postcode, headcount and founding-year fields — more corporate detail than most directories ask of a solo maker.","Pressing Send clears every field and prints nothing, so success and silent failure look identical.","Inclusion is discretionary with no published review window, so there is no date to chase."]', rw_faq='[{"question":"How long does RankmyAI approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to RankmyAI?","answer":"Submitting is free."},{"question":"Does a RankmyAI listing provide a dofollow link?","answer":"No — tool names are plain text with no anchor at all on a domain rated 35."},{"question":"Do I need to link back to RankmyAI?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A tool without meaningful AI or hosted on a shared path."}]', rw_summary='RankmyAI is a free research ranking with no backlink — tool names carry no anchor — and a discretionary review. Domain rating is 35.', rw_fact_points='["No published review time","Free listing with no link at all","No required backlink","Accepts AI tools with their own domain"]', rw_submission_checks='["No backlink — names are plain text.","A legal company name is required.","Success and failure look identical."]', rw_seo_title='RankmyAI: Free Research Listing, DR 35', rw_seo_description='How to submit to RankmyAI: free research-database listing with no backlink. Company name required — 2026-11-16 snapshot.' WHERE slug='rankmyai';
UPDATE submission_sites SET rw_source_lead='A small-SaaS launch board: free with a verified badge and up to 30 days, or $9.90 to skip the queue.', rw_what_you_get='A dofollow launch listing for a verified badge, published within 30 days at 08:00 UTC.', rw_you_need='["A live URL and a Google or GitHub account","A square logo and a 16:9 product image","Their badge verified on your site for free"]', rw_eligibility='You need an account, media and — on free — a badge. Nothing is published about who is refused.', rw_submit_steps='["1 Sign in with Google or GitHub; the submit route redirects there and back.","2 Project Info: a name, URL with an AI Autofill button, an optional affiliate URL, a rich-text short description, a square logo and a 16:9 product image.","3 Details: up to three categories from a long list, up to five tech tags, platforms, pricing and optional GitHub and Twitter URLs.","4 Launch Type and Date. Free Launch (Verified Badge) is preselected; the badge snippet sits under verification — tick that you added it and press Verify Backlink before Next.","5 Review and submit. Launches go out at 08:00 UTC on the day the queue reaches you."]', rw_submit_requirements='["A project name, website URL and short description","A 1:1 logo around 256x256 and a 16:9 image around 800x450","Up to three categories and five tech tags","Their badge verified before submit on free"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The badge is verified on the launch-date step before review, so the free lane cannot be submitted until it is live and the checker has seen it.","The free queue is up to 30 days and launches only at 08:00 UTC; Premium $9.90 is the only way to pick the date.","The DR Booster on the last step is ten links from the operator''s own directory network for $50, sold under the plan cards as if part of the launch."]', rw_faq='[{"question":"How long does Smol Saas approval take?","answer":"Two to four weeks; the free card states up to 30 days."},{"question":"How much does it cost to submit to Smol Saas?","answer":"Free with a verified badge and a 30-day queue for a followed link. $9.90 Premium skips the queue; $12.90 Premium Plus adds promotion; $49 SEO package and $50 DR Booster are sold separately."},{"question":"Does a Smol Saas listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 35."},{"question":"Do I need to link back to Smol Saas?","answer":"Yes — a badge is required on free."},{"question":"What gets a listing rejected?","answer":"Nothing published."}]', rw_summary='Smol Saas is a free dofollow small-SaaS launch board gated on a verified badge, with a 30-day queue and no other backlink. DR 35.', rw_fact_points='["Free launch within 30 days at 08:00 UTC","Dofollow link, badge required on free","Badge verified before review","Accepts small SaaS and dev tools"]', rw_submission_checks='["Verify the badge before the date step.","Free cannot pick the launch date.","The $50 DR Booster is a separate network."]', rw_seo_title='Smol Saas: Free Badge Launch, DR 35', rw_seo_description='How to launch on Smol Saas: free dofollow listing for a verified badge, 30-day queue. Rules from the 2026-11-16 snapshot.' WHERE slug='smolsaas';
UPDATE submission_sites SET rw_source_lead='An AI tools directory selling $49 and $99 lifetime listings, whose free route is not on the submit page at all but in one line of the pricing FAQ.', rw_what_you_get='A dofollow listing for $49 or $99, or a hidden free route through the contact form with a 30-day review.', rw_you_need='["A product their editors judge fit for an AI audience","$49, or the patience for the free route''s 30-day review"]', rw_eligibility='You need a fitting product. NSFW tools are refused outright, and the terms let editors remove any listing later as inappropriate.', rw_submit_steps='["1 Read the pricing page: two paid tiers at $49 and $99, and an FAQ answer that free listings are requested through Contact Us.","2 Pay, or write. Submit Tool leads to the paid flow; the free route is the contact form with product details in the message body.","3 Clear the captcha. The contact form carries a reCAPTCHA that a person must tick.","4 Wait for editorial: two days on Premium, four on Basic, thirty on free."]', rw_submit_requirements='["A product name and URL typed into the message on free","A short description as prose in that message and a contact email","$49 optional, with logo and screenshots optional"]', rw_rejection_reasons='["NSFW tools, and anything editors later judge inappropriate — the terms allow removal at any point"]', rw_gotchas='["The free route is one sentence in the pricing FAQ and appears nowhere on the submit page, so stopping at Submit Tool suggests the cheapest way in is $49.","That free route runs through a contact form with no product fields — just a name, email and one message box, so everything goes in as prose.","A reCAPTCHA sits between the filled form and Submit, so the last step needs a person.","The terms allow removal at any point if editors later judge a listing inappropriate — paid tiers included despite the lifetime wording."]', rw_faq='[{"question":"How long does The AI Surf approval take?","answer":"One to two months; free states 30 days, Basic four and Premium two."},{"question":"How much does it cost to submit to The AI Surf?","answer":"$49 Basic or $99 Premium once, both permanent. A free listing exists only through the contact form with a 30-day review and fewer features."},{"question":"Does a The AI Surf listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 35."},{"question":"Do I need to link back to The AI Surf?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"NSFW tools and anything editors later judge inappropriate."}]', rw_summary='The AI Surf is a $49+ dofollow AI directory with no backlink and a hidden free route via the contact form. Domain rating is 35.', rw_fact_points='["Thirty-day free review","Paid tiers or hidden free route, dofollow","No required backlink","Accepts AI tools and apps"]', rw_submission_checks='["The free lane is only in the pricing FAQ.","Free goes through a contact form with a captcha.","Paid listings can still be removed."]', rw_seo_title='The AI Surf: $49+ Dofollow Listing, DR 35', rw_seo_description='How to submit to The AI Surf: $49+ dofollow listing, no backlink. Free route hidden in the FAQ — 2026-11-16 snapshot.' WHERE slug='theaisurf';
UPDATE submission_sites SET rw_source_lead='A badge-first AI app directory where the free listing is the only listing and the link is followed.', rw_what_you_get='A dofollow listing gated behind a live badge check on your nominated page.', rw_you_need='["An account via Google or email","Their badge checked live before the form appears","An uploaded screenshot and square icon and a description up to 150 characters"]', rw_eligibility='You need an account, a reachable site and a badge. Anyone who cannot host the badge, or whose page the crawler cannot reach, is out.', rw_submit_steps='["1 Sign in with Google or an email account created with them.","2 Add your website — the product homepage, from which the badge and listing slug are generated.","3 Badge and verify. Light and dark snippets point at your listing; name the page to fetch and press Verify Badge to open step three.","4 Details: a site name, screenshot, icon, up to four categories, a pricing model, a 150-character short description and a 1,500-character overview, then terms and Submit for Review."]', rw_submit_requirements='["An account and their live-verified 209x54 PNG badge","A site name and a screenshot up to 10MB","A square icon up to 5MB and up to four categories","A pricing model, a 150-character summary and a 1,500-character overview"]', rw_rejection_reasons='["A site that cannot carry the badge, or one the crawler cannot reach"]', rw_gotchas='["The whole form sits behind the badge check — step three does not exist until the crawler finds it.","Their snippet asks for a do-follow link to your listing URL, stricter than usual, so a site that nofollows footer links must make an exception.","No review window is published — the success page only says the tool is under review.","The success page cross-offers a grid of sister directories from the same operator."]', rw_faq='[{"question":"How long does The App Tools approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to The App Tools?","answer":"Submitting is free with a badge."},{"question":"Does a The App Tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 36."},{"question":"Do I need to link back to The App Tools?","answer":"Yes — a badge is required."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry the badge or that the crawler cannot reach."}]', rw_summary='The App Tools is a free dofollow AI-app directory with a live badge gate and no other backlink. Domain rating is 36.', rw_fact_points='["No published review time","Free listing with a dofollow link","A live badge gates the form","Accepts AI apps and SaaS"]', rw_submission_checks='["Install the badge before the form appears.","Make it dofollow to the reserved URL.","Reach overlaps with sister directories."]', rw_seo_title='The App Tools: Free Badge Listing, DR 36', rw_seo_description='How to submit to The App Tools: free dofollow AI-app listing gated on a live badge. Rules from the 2026-11-16 snapshot.' WHERE slug='theapptools';
UPDATE submission_sites SET rw_source_lead='A badge-first software directory where the free listing is the only listing and the link is followed.', rw_what_you_get='A dofollow listing gated behind a live badge check on your nominated page.', rw_you_need='["An account via Google or email","Their badge checked live before the form appears","An uploaded screenshot and square icon and a description up to 150 characters"]', rw_eligibility='You need an account, a reachable site and a badge. Anyone who cannot host the badge, or whose page the crawler cannot reach, is out.', rw_submit_steps='["1 Sign in with Google or an email account created with them.","2 Add your website — the product homepage, from which the badge and listing slug are generated.","3 Badge and verify. Light and dark snippets point at your listing; name the page to fetch and press Verify Badge to open step three.","4 Details: a site name, screenshot, icon, up to four categories, a pricing model, a 150-character short description and a 1,500-character overview, then terms and Submit for Review."]', rw_submit_requirements='["An account and their live-verified 216x54 PNG badge","A site name and a screenshot up to 10MB","A square icon up to 5MB and up to four categories","A pricing model, a 150-character summary and a 1,500-character overview"]', rw_rejection_reasons='["A site that cannot carry the badge, or one the crawler cannot reach"]', rw_gotchas='["The whole form sits behind the badge check — step three does not exist until the crawler finds it.","Their snippet asks for a do-follow link to your listing URL, stricter than usual, so a site that nofollows footer links must make an exception.","No review window is published — the success page only says the tool is under review.","The success page cross-offers a grid of sister directories from the same operator."]', rw_faq='[{"question":"How long does The Core Tools approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to The Core Tools?","answer":"Submitting is free with a badge."},{"question":"Does a The Core Tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 36."},{"question":"Do I need to link back to The Core Tools?","answer":"Yes — a badge is required."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry the badge or that the crawler cannot reach."}]', rw_summary='The Core Tools is a free dofollow software directory with a live badge gate and no other backlink. Domain rating is 36.', rw_fact_points='["No published review time","Free listing with a dofollow link","A live badge gates the form","Accepts SaaS, AI tools and dev tools"]', rw_submission_checks='["Install the badge before the form appears.","Make it dofollow to the reserved URL.","Reach overlaps with sister directories."]', rw_seo_title='The Core Tools: Free Badge Listing, DR 36', rw_seo_description='How to submit to The Core Tools: free dofollow software listing gated on a live badge. Rules from the 2026-11-16 snapshot.' WHERE slug='thecoretools';
UPDATE submission_sites SET rw_source_lead='A weekly launch board whose free lane pays a real followed link for a badge, with launches every Monday.', rw_what_you_get='A dofollow listing for a verified badge, published immediately and scheduled for a coming Monday.', rw_you_need='["An account via Google, GitHub or email","Their badge on your site before the form will let you finish","A logo and a wide product image, both uploaded"]', rw_eligibility='You need an account, media and a reachable site that can carry the badge. The fourth step will not unlock without their checker finding it.', rw_submit_steps='["1 Sign in with Google, GitHub or email and password.","2 Project Info: a name, website URL, an optional affiliate URL, a rich-text short description, then a logo and product image as uploads.","3 Details: up to three searchable categories, up to five tech tags, platforms, pricing and optional GitHub and Twitter URLs.","4 Launch Type and badge. Free Launch shows the badge snippet, a checkbox and Verify Backlink; Next stays disabled until the check passes.","5 Review and submit. The listing publishes immediately, scheduled for a coming Monday."]', rw_submit_requirements='["An account and their 150x44 SVG badge verified live","A product name and rich-text short description","A 1:1 logo and up to three categories","Up to five tech tags and an optional wide product image"]', rw_rejection_reasons='["A site that cannot carry the badge — step four will not unlock — or one the crawler cannot reach"]', rw_gotchas='["The badge must be live before step four will let you through, but the snippet points at a page that does not exist until the first two steps are filled, so it cannot be put up in advance.","Launches run once a week on Mondays rather than daily, so the queue moves in weekly steps.","An AI Autofill button can write the whole listing from your URL — a fast way to publish copy nobody wrote."]', rw_faq='[{"question":"How long does TinyHunt approval take?","answer":"One to two weeks; the free card states listing within 14 days."},{"question":"How much does it cost to submit to TinyHunt?","answer":"Free Launch is $0 for a badge and a followed link within 14 days. Premium $9.90, Premium Plus $12.90, a $49 SEO package and a $50 ten-site DR Booster are sold separately."},{"question":"Does a TinyHunt listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 35."},{"question":"Do I need to link back to TinyHunt?","answer":"Yes — a badge is required on free."},{"question":"What gets a listing rejected?","answer":"A site that cannot carry the badge or that the crawler cannot reach."}]', rw_summary='TinyHunt is a free dofollow weekly launch board gated on a verified badge, with Monday launches and no other backlink. DR 35.', rw_fact_points='["Launch within 14 days, Mondays only","Dofollow link gated on a badge","Badge verified live before step four","Accepts SaaS, indie products and AI tools"]', rw_submission_checks='["The badge URL does not exist until steps one and two.","Launches are weekly, not daily.","An AI Autofill can write the listing."]', rw_seo_title='TinyHunt: Free Badge Launch, DR 35', rw_seo_description='How to launch on TinyHunt: free dofollow listing for a badge, Monday launches. Badge caveat from the 2026-11-16 snapshot.' WHERE slug='tinyhunt';
UPDATE submission_sites SET rw_source_lead='The submit form looks free and is not: fill four fields and the next screen is a paywall starting at $9.99.', rw_what_you_get='A dofollow listing that costs $9.99 upward, with the price hidden until after the four-field form.', rw_you_need='["A live tool URL and an email","At least $9.99"]', rw_eligibility='You need to pay and a live tool. Nothing is published about a moderation bar.', rw_submit_steps='["1 Fill four fields: a tool name, a tool link, your email and an optional description. It reads as a free submission.","2 Meet the paywall. Next goes to a page headed Choose a Plan to Complete Your Submission: Basic $9.99, Gold $39.99, Platinum $159.99, all one-time.","3 Pay and wait. Basic processes in up to five days, Gold up to three, Platinum up to 48 hours; screenshots, description and tags come from Gold up."]', rw_submit_requirements='["A tool name and link and an email","A payment from $9.99 and an optional description"]', rw_rejection_reasons='["Nothing published — the moderation bar looks low in practice"]', rw_gotchas='["The submission form is a lead capture, not a submission — you hand over your name, link and email before being told the listing costs at least $9.99.","Submitting also opts you into the weekly newsletter with no separate checkbox; consent is bundled into a line above the button.","They advertise DR 43+ on one page and 40+ on the next, while the domain measures 36. The dofollow link is real, spelled out in the markup."]', rw_faq='[{"question":"How long does Toolio approval take?","answer":"Three to five days; Basic up to five, Gold up to three, Platinum up to 48 hours."},{"question":"How much does it cost to submit to Toolio?","answer":"$9.99 Basic, $39.99 Gold, $159.99 Platinum, all one-time. No free tier despite the form''s appearance."},{"question":"Does a Toolio listing provide a dofollow link?","answer":"Yes, a real dofollow link on a domain measured at 36, despite higher DR claims."},{"question":"Do I need to link back to Toolio?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published."}]', rw_summary='Toolio is a paid-only $9.99+ dofollow directory with no backlink, whose four-field form hides the paywall. Domain rating is actually 36.', rw_fact_points='["Three-to-five-day review","Paid-only from $9.99, dofollow","No badge or return link is expected","Accepts AI tools and SaaS"]', rw_submission_checks='["The form captures details before showing the price.","Newsletter consent is bundled in.","Advertised DR exceeds measured DR."]', rw_seo_title='Toolio: $9.99 Dofollow Listing, DR 36', rw_seo_description='How to submit to Toolio: $9.99+ dofollow listing, no backlink. Hidden paywall from the 2026-11-16 snapshot.' WHERE slug='toolio';
UPDATE submission_sites SET rw_source_lead='An AI tools directory with a genuinely free listing and a followed link, whose form wants key features rather than a paragraph.', rw_what_you_get='A dofollow listing on free with no backlink, if you can supply key features as separate rows and wait an open-ended queue.', rw_you_need='["An account via Google or an emailed magic link","At least one key feature and a hero screenshot under 5MB"]', rw_eligibility='You need a recognisably AI tool with key features listed. Anything not an AI tool, or anyone needing a date for free, is out.', rw_submit_steps='["1 Sign in with Google or an email magic link — there is no password option.","2 Basic information: a tool name, a one-line short description, a long description, an optional company, your name and a hero screenshot.","3 Links and pricing: a website URL, optional docs and GitHub URLs and a pricing model of Free, Freemium, Paid or Contact.","4 Details: searchable categories, one or more key features as separate rows, supported platforms and optional tutorials.","5 Declare and choose: a checkbox asking whether you are associated with the product, then Regular free, Featured Fast-Track $49 or the $299 bundle."]', rw_submit_requirements='["An account and a tool name with a one-line and a long description","Your name and a hero screenshot up to 5MB","At least one key feature as its own row and supported platforms","Optional docs, GitHub URLs and tutorials"]', rw_rejection_reasons='["Anything not recognisably an AI tool, and anyone needing a date — the free queue has no published window"]', rw_gotchas='["Key Features is required and is a list of separate rows rather than a paragraph, so a pack holding only a description has nothing to put in it.","A checkbox asks whether you are associated with the product — a declaration, not a formality, and easy to leave unticked.","The free queue has no published window — their card says only it can take a while, and the $49 tier sells on skipping it.","Upsells keep coming after submission: a modal offers a $249 newsletter spotlight the moment the tool enters the queue."]', rw_faq='[{"question":"How long does WhatTheAI approval take?","answer":"No review time is published for free — their card says it can take a while."},{"question":"How much does it cost to submit to WhatTheAI?","answer":"Regular listing free with an open-ended queue. Featured Fast-Track $49 once for priority review; a $299 Exposure Bundle adds a written blog post and founder interview."},{"question":"Does a WhatTheAI listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 36."},{"question":"Do I need to link back to WhatTheAI?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Anything not recognisably an AI tool, or needing a free-lane date."}]', rw_summary='WhatTheAI is a free dofollow AI directory with no backlink, needing key features as rows and an open-ended free queue. DR 36.', rw_fact_points='["Free queue with no published window","Free listing with a dofollow link","No required backlink","Accepts AI tools and SaaS"]', rw_submission_checks='["Key features are required as separate rows.","Tick the association declaration.","A $249 upsell follows acceptance."]', rw_seo_title='WhatTheAI: Free Dofollow Listing, DR 36', rw_seo_description='How to submit to WhatTheAI: free dofollow AI listing, no backlink. Key-features requirement from the 2026-11-16 snapshot.' WHERE slug='whattheai';
UPDATE submission_sites SET rw_source_lead='A design inspiration gallery that judges how a site looks rather than what it does, free to submit in two fields with a three-to-four-week queue.', rw_what_you_get='A dofollow spot in a taste-driven design gallery, judged on looks and free with a stated three-to-four-week wait.', rw_you_need='["An account via Google in one click or an email link","A site whose design is the reason to look at it"]', rw_eligibility='You need a site that wins on looks — editors pick on taste. Anything submitted for function, or needing a decision inside a month, is out.', rw_submit_steps='["1 Sign in with Google in one click or an email link; the submit page shows only a login prompt until you do.","2 Pick a type — Website or Template — as tabs above the form.","3 Fill two fields: the site link and, optionally, other creators as a website or social link. That is the whole form.","4 Wait three to four weeks on free; Pro submissions are reviewed first."]', rw_submit_requirements='["An account and a website link as the only required field","An optional other-creators website or social link"]', rw_rejection_reasons='["Anything submitted on the strength of what it does rather than how it looks, and anyone needing a decision inside a month"]', rw_gotchas='["This is a taste gallery, not a directory — their copy says they feature a site only if they like it too, so most nominations are never published.","Signed out, the submit page shows a login prompt and no form, so the two-field form and the wait cannot both be read in one visit.","The free queue is three to four weeks by their own admission, and Pro submissions are reviewed ahead of it."]', rw_faq='[{"question":"How long does A1 Gallery approval take?","answer":"Two to four weeks; the free queue is stated at three to four weeks."},{"question":"How much does it cost to submit to A1 Gallery?","answer":"Submitting is free with a three-to-four-week queue. A1 Pro buys reviewed-first submissions, unlimited saves and 20% off templates."},{"question":"Does an A1 Gallery listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 33."},{"question":"Do I need to link back to A1 Gallery?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"Being nominated for function rather than looks, or needing a fast decision."}]', rw_summary='A1 Gallery is a free dofollow design gallery with no backlink, judged on taste with a three-to-four-week queue. Domain rating is 33.', rw_fact_points='["Free queue of three to four weeks","Free listing with a dofollow link","No required backlink","Accepts designed websites and templates"]', rw_submission_checks='["Editors pick on taste — most are declined.","The form is behind sign-in.","Pro skips the queue."]', rw_seo_title='A1 Gallery: Free Design Listing, DR 33', rw_seo_description='How to submit to A1 Gallery: free dofollow design-gallery spot, no backlink. Three-to-four-week queue from the 2026-11-16 snapshot.' WHERE slug='a1-gallery';
UPDATE submission_sites SET rw_source_lead='A free dofollow listing with no account at all, behind a queue they put at ninety days.', rw_what_you_get='A dofollow listing with no account and no backlink, if you can write 50+ words and wait 90 days.', rw_you_need='["A short description of 30 words or fewer and a long one of 50 to 500","A live website URL and an email address"]', rw_eligibility='You need a real AI tool with citable copy. Anything not an AI tool, or a description under 50 words, is refused.', rw_submit_steps='["1 Take the free lane from the pricing block. The submit page is a pricing page; Submit for Free goes to its own route.","2 Fill one screen: an email, tool name, a short description counted in words up to 30, a long one counted the same way from 50 to 500, one of eighteen categories, a primary use case, the website and an optional social URL.","3 Answer the advertising question — a required pair of radios asks whether you want ads at $0.10 a click; No, not at this time is accepted.","4 Submit and read the offers. The success page reads Submission Received!, with a free link back or $29 for a 48-hour review underneath."]', rw_submit_requirements='["An email and a tool name","A short description of 10 to 30 words and a long one of 50 to 500","One of eighteen categories, a primary use case and a website URL","An optional social URL"]', rw_rejection_reasons='["Anything that is not an AI tool, and a description shorter than 50 words — the form counts and refuses"]', rw_gotchas='["The free queue is 90 days or more by their own statement, repeated twice before you fill anything.","Both descriptions are counted in words, not characters, with a hard 50-word floor on the long one — a tagline and a short paragraph will not clear it.","A newsletter modal opens over the form and resets the advertising radios when it closes. Check them before submitting."]', rw_faq='[{"question":"How long does AISuperHub approval take?","answer":"Three to six months; free is stated at 90 days or more."},{"question":"How much does it cost to submit to AISuperHub?","answer":"Free with no account and a stated dofollow link. $49 Premium places within 48 hours; after submitting they also offer a free link back or $29 priority review."},{"question":"Does an AISuperHub listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 34."},{"question":"Do I need to link back to AISuperHub?","answer":"No backlink is required, though a free link back is offered to skip the queue."},{"question":"What gets a listing rejected?","answer":"A non-AI tool or a description under 50 words."}]', rw_summary='AISuperHub is a free no-account dofollow AI directory with no backlink, a 90-day queue and word-count minimums. Domain rating is 34.', rw_fact_points='["Free queue of 90 days or more","Free listing with a dofollow link","No required backlink","Accepts AI tools only"]', rw_submission_checks='["The long description needs 50 words minimum.","The newsletter modal resets the ad radios.","$29 buys a 48-hour review."]', rw_seo_title='AISuperHub: Free Dofollow Listing, DR 34', rw_seo_description='How to submit to AISuperHub: free no-account dofollow listing, no backlink. 90-day queue — 2026-11-16 snapshot.' WHERE slug='aisuperhub';
UPDATE submission_sites SET rw_source_lead='Nine dollars to be listed, and the link on a real listing is nofollow.', rw_what_you_get='A nofollow listing for $9 once, with seven days of category visibility — placement, not link equity.', rw_you_need='["$9 and a genuinely AI-based tool"]', rw_eligibility='You need to pay and a real AI tool. Adult, NSFW, gambling, duplicates and non-AI tools are refused.', rw_submit_steps='["1 Read the disclaimer. The submit page is mostly conditions: AI tools only, no adult or gambling, non-refundable payments and a request to search for a duplicate first.","2 Pay the fee. One tier at $9, described as a fast track listing within 48 hours with prime category visibility for seven days."]', rw_submit_requirements='["A $9 one-time non-refundable payment","A tool URL and tool details"]', rw_rejection_reasons='["Adult, NSFW, gambling and similar, duplicates, and anything not genuinely AI-based"]', rw_gotchas='["The $9 buys a nofollow link — a live listing''s only outbound anchor carried rel=nofollow noreferrer noopener external.","Payments are non-refundable once processed, and the refusal rules sit above the button.","They ask you to search first, because a duplicate becomes your problem once the fee is paid."]', rw_faq='[{"question":"How long does AiToolMate approval take?","answer":"One to two days; the fast track states 48 hours."},{"question":"How much does it cost to submit to AiToolMate?","answer":"$9 once, non-refundable. No free lane."},{"question":"Does an AiToolMate listing provide a dofollow link?","answer":"No — links are nofollow on a domain rated 33."},{"question":"Do I need to link back to AiToolMate?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Adult, gambling, duplicates and anything not genuinely AI-based."}]', rw_summary='AiToolMate is a paid-only $9 nofollow AI directory with no backlink. Domain rating is 33.', rw_fact_points='["48-hour fast track","Paid-only at $9, nofollow","No badge or return link is expected","Accepts AI tools"]', rw_submission_checks='["The $9 link is nofollow.","Payment is non-refundable.","Search for duplicates first."]', rw_seo_title='AiToolMate: $9 Nofollow Listing, DR 33', rw_seo_description='How to submit to AiToolMate: $9 one-time nofollow AI listing, no backlink. Non-refundable — 2026-11-16 snapshot.' WHERE slug='aitoolmate';
UPDATE submission_sites SET rw_source_lead='An AI tools directory whose cheapest listed plan is $79, whose free listing exists only in an FAQ answer, and whose homepage counters all read zero.', rw_what_you_get='A dofollow listing for $79+, or a free route through the contact form with no stated answer time.', rw_you_need='["An AI-looking product and $79, or a message through the contact form"]', rw_eligibility='You need a fitting product. Anyone needing a date on free, or unable to clear a captcha by hand, is out.', rw_submit_steps='["1 Read the pricing page. Three tiers at $79, $279 and $399 plus a $49 resubmission; every Submit AI link lands here.","2 Or write instead. The FAQ says a free basic listing is available, but there is no form — the contact page is the route with a name, email, URL and message box.","3 Clear the captcha. Send Message is disabled until a reCAPTCHA is ticked, which needs a person.","4 Wait. Paid tiers publish in 6 to 48 hours; nothing states how long free takes."]', rw_submit_requirements='["A product name, contact email and website URL","A description as prose in the message box","$79 optional"]', rw_rejection_reasons='["Needing a date — the free route has no window — and being unable to clear the captcha by hand"]', rw_gotchas='["There is no free form; the one sentence promising a free listing sits in a collapsed FAQ, and the only way to ask is the contact page.","Nothing states what free gets or how long it takes, while paid publishes in 6 to 48 hours.","The homepage prints 0 tools, 0K visitors and 0 users, so the audience figures the pricing page sells against cannot be checked.","Send Message stays disabled behind a reCAPTCHA, so the last step needs a person."]', rw_faq='[{"question":"How long does AllAIWebsite approval take?","answer":"No time is published; paid tiers are 6 to 48 hours, free has no window."},{"question":"How much does it cost to submit to AllAIWebsite?","answer":"$79 Fast Listing within 48 hours, $279 Verified within 24 hours, $399 Featured within 6 hours, $49 resubmission. A free basic listing is mentioned in the FAQ but has no form."},{"question":"Does an AllAIWebsite listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 33."},{"question":"Do I need to link back to AllAIWebsite?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Needing a free-lane date or failing the captcha."}]', rw_summary='AllAIWebsite is a $79+ dofollow AI directory with no backlink and a free route hidden in the FAQ that has no form. Domain rating is 33.', rw_fact_points='["Paid review in 6 to 48 hours","Paid tiers dofollow, no backlink","No badge or return link is expected","Accepts AI tools and apps"]', rw_submission_checks='["The free lane exists only in the FAQ.","Homepage counters all read zero.","A captcha gates the contact form."]', rw_seo_title='AllAIWebsite: $79+ Dofollow Listing, DR 33', rw_seo_description='How to submit to AllAIWebsite: $79+ dofollow listing, no backlink. Hidden free route from the 2026-11-16 snapshot.' WHERE slug='allaiwebsite';
UPDATE submission_sites SET rw_source_lead='Free and manually reviewed, with the followed link paid for by a social post rather than money.', rw_what_you_get='A nofollow listing on submit that becomes dofollow through a social share or a badge once approved.', rw_you_need='["A product name, URL, a tagline under 100 and a contact email","One to three of fifteen categories and a square logo","To earn the follow: a social post or their badge"]', rw_eligibility='You need a product that passes their linked submission guidelines under human review.', rw_submit_steps='["1 Skip the Product Hunt import. The optional box fills everything from a PH URL — leave it empty if never launched there.","2 Fill the form: a name, website, a tagline up to 100, a contact email, one to three of fifteen categories, a description and a logo by upload or pasted image URL.","3 Tick the email agreement and submit. The answer appears in place with Submission Received! and Status: Pending Review.","4 Earn the dofollow. The confirmation offers a share on X or LinkedIn using their prepared text, or their badge, which unlocks once the product is live."]', rw_submit_requirements='["A product name, website URL and tagline up to 100","A contact email and one to three categories","A description and a square logo, upload or URL","An optional gallery of three or more"]', rw_rejection_reasons='["Anything that fails their linked submission guidelines under review"]', rw_gotchas='["The link from a plain submission is nofollow — their panel says dofollow goes to makers who support the community, and the badge that earns it does not exist until approval.","The logo accepts a pasted image URL as well as an upload, which is the difference between a two-minute submission and a file hunt.","Nothing auto-publishes — their line under the button says manual approval is required, and no review time is stated."]', rw_faq='[{"question":"How long does Inuidea Hunt approval take?","answer":"No review time is published; every submission is manually reviewed."},{"question":"How much does it cost to submit to Inuidea Hunt?","answer":"Submitting is free; the dofollow is earned with a social share or badge."},{"question":"Does an Inuidea Hunt listing provide a dofollow link?","answer":"No by default — links are nofollow on a domain rated 34 until a share or badge earns the follow."},{"question":"Do I need to link back to Inuidea Hunt?","answer":"No required backlink, though a badge or social post earns the dofollow."},{"question":"What gets a listing rejected?","answer":"Anything that fails their linked submission guidelines."}]', rw_summary='Inuidea Hunt is a free manually reviewed directory with no required backlink, where a social share or badge upgrades a nofollow listing to dofollow. DR 34.', rw_fact_points='["Human review, no published time","Free listing starts nofollow","Social share or badge earns the follow","Accepts indie products and SaaS"]', rw_submission_checks='["Plain submission gets nofollow.","A logo URL avoids an upload.","The badge unlocks only after approval."]', rw_seo_title='Inuidea Hunt: Free Earned-Dofollow Listing, DR 34', rw_seo_description='How to submit to Inuidea Hunt: free manual review, no backlink. Dofollow earned by social share or badge — 2026-11-16 snapshot.' WHERE slug='inuidea-hunt';
UPDATE submission_sites SET rw_source_lead='Publishes the moment you list, with a real dofollow, and the free lane is paid for with a dofollow badge of their own.', rw_what_you_get='An instant dofollow listing for your own domain, bought with a followed badge on your homepage or $19.', rw_you_need='["Your own domain — free-host subdomains like vercel.app are refused","An account via Google, and either their badge or $19"]', rw_eligibility='You need a custom domain and an account. Anything on a shared host or builder subdomain is refused by policy.', rw_submit_steps='["1 Paste your URL and let it scan. One field; their AI reads your site and drafts the name, tagline, description, category and a screenshot.","2 Sign in when it asks. The login wall appears at the scan, not before; Google is offered with email and password, and the URL survives the round trip.","3 Rewrite what the AI wrote. The draft is a paraphrase of your homepage, editable, with a description that will not go below 80 characters.","4 Choose the badge or $19. Free asks for their badge on your homepage linking dofollow to their startups page, then a Verify now button checks it; paid skips the badge."]', rw_submit_requirements='["An account and your own-domain product URL","A name, tagline and a description of at least 80 characters","One of twelve categories and their dofollow homepage badge on free"]', rw_rejection_reasons='["Anything on a shared host or a builder subdomain, refused by the URL field''s policy"]', rw_gotchas='["Their AI writes the listing before you see it, as a paraphrase of your homepage — read every field and replace it.","The free lane wants a dofollow link back, in those words, checked against what is deployed rather than what you have written.","The site''s other half is a Product Hunt upvote pact with reciprocal voting, which PH''s rules frown on — a separate decision from being listed.","The FAQ describes a bid-from-$15 model and says the free badge lane is gone, which conflicts with the submit flow still offering it."]', rw_faq='[{"question":"How long does LaunchPact approval take?","answer":"Instant — the listing publishes as soon as badge or payment clears."},{"question":"How much does it cost to submit to LaunchPact?","answer":"The submit flow offers a free lane with a dofollow badge or $19 with no badge; the FAQ instead describes bids from $15 and calls the free lane gone. A separate $34 launch pact is optional."},{"question":"Does a LaunchPact listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 34."},{"question":"Do I need to link back to LaunchPact?","answer":"Yes on the free lane — a dofollow badge is required."},{"question":"What gets a listing rejected?","answer":"Anything on a shared host or builder subdomain."}]', rw_summary='LaunchPact is an instant dofollow launch board for custom domains, gated on a badge or $19, with no other backlink. DR 34.', rw_fact_points='["Instant publication","Dofollow link for a badge or $19","Badge required on free","Accepts custom-domain SaaS and startups"]', rw_submission_checks='["Replace the AI-written copy.","The free badge must be dofollow.","FAQ and submit flow disagree on pricing."]', rw_seo_title='LaunchPact: Free Badge Listing, DR 34', rw_seo_description='How to submit to LaunchPact: instant dofollow listing for a badge or $19. Custom domain required — 2026-11-16 snapshot.' WHERE slug='launchpact';
UPDATE submission_sites SET rw_source_lead='A zoomable map of a million homepages, where a listing is a screenshot tile rather than an entry.', rw_what_you_get='A rendered screenshot tile in a visual map, with no outbound link — worth doing for the picture, not SEO.', rw_you_need='["A live homepage worth rendering and an email address"]', rw_eligibility='You need a site with something to look at — the whole listing is a picture of your homepage.', rw_submit_steps='["1 Open the suggestion form. Suggest in the footer or the direct route opens a two-field form headed Suggest a Site.","2 Give an email and a bare domain. The website field wants the domain alone — a full https:// URL is refused.","3 Submit. The form posts and answers on its own page with Form details submitted successfully."]', rw_submit_requirements='["An email address and a bare domain, not a full URL"]', rw_rejection_reasons='["Anything with nothing to look at — the listing is a picture of your homepage"]', rw_gotchas='["The website field refuses a full https:// URL with Website is invalid and gives no hint beyond the acme.com placeholder that it wants a bare domain.","There is no link — a site page carries no outbound anchor to the site it shows.","Nothing states a review time; their only promise is to let you know when the site is added."]', rw_faq='[{"question":"How long does OneMillionScreenshots approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to OneMillionScreenshots?","answer":"Submitting is free."},{"question":"Does a OneMillionScreenshots listing provide a dofollow link?","answer":"No — there is no outbound anchor at all on a domain rated 34."},{"question":"Do I need to link back to OneMillionScreenshots?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"A homepage with nothing worth looking at."}]', rw_summary='OneMillionScreenshots is a free no-backlink visual map of homepages where a listing is a screenshot tile with no outbound link. DR 34.', rw_fact_points='["No published review time","Free listing with no link at all","No required backlink","Accepts visual websites"]', rw_submission_checks='["Enter a bare domain, not a URL.","There is no outbound link.","No review window is stated."]', rw_seo_title='OneMillionScreenshots: Free Site Tile, DR 34', rw_seo_description='How to submit to OneMillionScreenshots: free screenshot-tile listing with no backlink. Bare domain rule from the 2026-11-16 snapshot.' WHERE slug='onemillionscreenshots';
UPDATE submission_sites SET rw_source_lead='A daily launch board on the open-source Open-Launch codebase, with five free slots a day booked months ahead and a $9 lane that skips them.', rw_what_you_get='A nofollow launch slot on a free calendar booked six months out, where dofollow is only a prize for the day''s top three.', rw_you_need='["An account via Google in one click","An uploaded logo and wide product image","A launch date on the calendar"]', rw_eligibility='You need an account, uploads and a date. A listing within six months on free is out, as is counting on the link — free stays nofollow unless you place top three.', rw_submit_steps='["1 Sign in. Google creates the account in one click, with no separate registration form.","2 Project Info: a name, URL, a tagline up to 160, a rich-text description, then a logo and product image as file uploads.","3 Details: up to three categories, up to five tech tags, platforms, pricing and optional GitHub and Twitter URLs.","4 Launch Date: Free or Premium Launch, then a date. The free calendar lists 180 days and greys out every full one.","5 Review and submit. A read-only summary, then Submit Project; the page exists immediately, marked Scheduled."]', rw_submit_requirements='["An account and a product name and tagline up to 160","A rich-text description and file-uploaded logo and wide image","Up to three categories and five tech tags"]', rw_rejection_reasons='["Needing a free listing inside six months, and counting on the link — free dofollow requires a top-three finish"]', rw_gotchas='["The free calendar offers 180 days and almost none are bookable — one date was open, six months out, on the day tested.","The followed link is a prize for the day''s top three; everything below keeps the nofollow it launched with.","This board is not open-launch.com, which runs the same code at a higher DR — listings do not carry across."]', rw_faq='[{"question":"How long does Open Launch approval take?","answer":"Six months or more on free; the calendar is booked to 180 days."},{"question":"How much does it cost to submit to Open Launch?","answer":"Free with five slots a day and a top-three-only dofollow; $9 Premium skips the queue with dofollow from day one, ten slots a day and seven days on the homepage."},{"question":"Does an Open Launch listing provide a dofollow link?","answer":"No by default — nofollow on a domain rated 34; top three on free or $9 buys the follow."},{"question":"Do I need to link back to Open Launch?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Needing a near-term free slot or relying on the link."}]', rw_summary='Open Launch is a free nofollow launch board with a near-full 180-day calendar, where top three or $9 buys the follow. No backlink; DR 34.', rw_fact_points='["Free calendar booked six months out","Free link nofollow; top-three or $9 for dofollow","No required backlink","Accepts SaaS, indie products and AI tools"]', rw_submission_checks='["Almost every free date is full.","Dofollow is a ranking prize.","This is not open-launch.com."]', rw_seo_title='Open Launch: Free Closed Board, DR 34', rw_seo_description='How to launch on Open Launch: free nofollow slot booked six months out, top-three or $9 for dofollow. Rules from the 2026-11-16 snapshot.' WHERE slug='openlaunch-ai';
UPDATE submission_sites SET rw_source_lead='An old-school web directory with a genuinely free lane and an image captcha at the end of it.', rw_what_you_get='A permanent dofollow link from $0, chosen before the form and finished with a captcha.', rw_you_need='["A category chosen by browsing first","A title, URL and description and a working email","A human at the image captcha"]', rw_eligibility='You need a real site and a live email. Gambling and excluded categories are refused, and a bouncing address gets the link removed.', rw_submit_steps='["1 Pick a listing type. Four radios head the form: lifetime featured $59, three months featured $9, lifetime top regular $19 and Regular link free.","2 Fill the listing: a title, URL and a description with a 1,000-character counter, optional meta keywords and description, and a checkbox for search/tag visibility.","3 Give contact details: a required name and email, with a warning that a bouncing address means immediate removal.","4 Answer the captcha. The last field is an image captcha headed Verification, with no other route past it."]', rw_submit_requirements='["A category chosen before the form and a title and URL","A description up to 1,000 characters and your name and email","An image captcha and optional deep links"]', rw_rejection_reasons='["Gambling and other excluded categories, and an email address that bounces — removed immediately"]', rw_gotchas='["The form ends on an image captcha, so the last step needs a person regardless of the rest.","The category is not on the form — it must be chosen by browsing first and travels as a hidden field reading 0 until then.","A bouncing email gets the listing removed immediately in their words, so a throwaway address costs the link later."]', rw_faq='[{"question":"How long does ProLinkDirectory approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to ProLinkDirectory?","answer":"Regular link free; lifetime featured $59, three months featured $9, lifetime top regular $19, and three deep links for $10 lifetime."},{"question":"Does a ProLinkDirectory listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 34."},{"question":"Do I need to link back to ProLinkDirectory?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Excluded categories like gambling, and an email that bounces."}]', rw_summary='ProLinkDirectory is a free permanent dofollow web directory with no backlink, where the category is chosen first and a captcha ends the form. DR 34.', rw_fact_points='["No published review time","Free listing with a dofollow link","No required backlink","Accepts general websites"]', rw_submission_checks='["Choose the category before the form.","A person must solve the captcha.","Use an email that will not bounce."]', rw_seo_title='ProLinkDirectory: Free Web Link, DR 34', rw_seo_description='How to submit to ProLinkDirectory: free permanent dofollow link, no backlink. Category-first form and captcha — 2026-11-16 snapshot.' WHERE slug='prolinkdirectory';
UPDATE submission_sites SET rw_source_lead='A permanent dofollow listing in exchange for a badge, behind an account that only a magic link opens.', rw_what_you_get='A permanent dofollow listing rented against a badge or text link, approved within seven days.', rw_you_need='["An account opened by a magic link to your email","Their badge or text link on your homepage for free","A live product URL"]', rw_eligibility='You need a magic-link account, a linkable site and software a team would buy. A free submission from a site that will not carry their badge is out.', rw_submit_steps='["1 Create the account. Signup asks for a name and email only; sign-in is a magic link with no password and no third-party option anywhere.","2 Pick a plan: Free, Pro $15 once or Featured $29 a month. The free row says Backlink or badge required.","3 Place the badge. Six options count equally — three 175x54 badges, two 64x64 squares and a plain text link — all pointing at their homepage.","4 Submit and wait a week. Free approval is within seven days; Pro places instantly."]', rw_submit_requirements='["A name and email with magic-link sign-in","Their badge or text link on free, from six options","A product URL, a description up to 1,200 and three tags"]', rw_rejection_reasons='["A free submission from a site that will not carry a badge or text link, and anything that is not software a team would buy"]', rw_gotchas='["There is no password and no Google or GitHub option — only a magic link to the signup address, so a shared or unmonitored inbox cannot open the account.","The arrangement is mutual and ongoing — their page calls it a backlink exchange, so the badge has to stay for the link to keep counting."]', rw_faq='[{"question":"How long does SaaS Cubes approval take?","answer":"About a week; free is within seven days, Pro is instant."},{"question":"How much does it cost to submit to SaaS Cubes?","answer":"Free forever with a badge for one permanent dofollow and seven-day approval; Pro $15 once drops the badge with a longer description and instant placement; Featured $29 a month."},{"question":"Does a SaaS Cubes listing provide a dofollow link?","answer":"Yes, a permanent dofollow link on a domain rated 33."},{"question":"Do I need to link back to SaaS Cubes?","answer":"Yes — a badge or text link is required on free."},{"question":"What gets a listing rejected?","answer":"A free submission without a badge, or a product that is not team software."}]', rw_summary='SaaS Cubes is a free dofollow SaaS directory with no other backlink, where a permanent badge buys the link and a magic link is the only account. DR 33.', rw_fact_points='["Seven-day free approval","Free listing with a dofollow link","A badge is required on free","Accepts SaaS and dev tools"]', rw_submission_checks='["The magic link needs a real inbox.","The badge must stay for the link to count.","$15 drops the badge."]', rw_seo_title='SaaS Cubes: Free Badge Listing, DR 33', rw_seo_description='How to submit to SaaS Cubes: free dofollow SaaS listing for a badge, seven-day approval. Magic-link from the 2026-11-16 snapshot.' WHERE slug='saascubes';
UPDATE submission_sites SET rw_source_lead='Free to launch with real analytics on views and clicks, and every outbound link routed through their own redirect.', rw_what_you_get='A free launch with view and click analytics, but no outbound link — Visit Website points at their own redirect.', rw_you_need='["An account via Google, GitHub, X or email and password","A live product"]', rw_eligibility='You need an account and a live product. Nothing is published as a refusal rule.', rw_submit_steps='["1 Sign in to the console with GitHub, Google or X, or email and password, through their auth provider.","2 Add the product inside the member console, not on a public submit page.","3 Launch free, upgrade later. The $0 tier gets the product page, a homepage feed card, browse and directory results, and the analytics; Featured and Pro buy priority placement."]', rw_submit_requirements='["An account and a product name, description and URL","Paid placement only if you want priority, optional"]', rw_rejection_reasons='["Nothing published"]', rw_gotchas='["There is no outbound link to earn — Visit Website points at a redirect on their own domain, so nothing reaches yours.","The compensation is measurement: free listings get views, visitors, audience insights and upvote tracking, which most directories reserve for paying accounts.","The sign-in is a separate console and looped back to login after a Google consent in testing."]', rw_faq='[{"question":"How long does Shipyard HQ approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Shipyard HQ?","answer":"The base launch is $0 with analytics; Featured and Pro placements are paid, once or recurring."},{"question":"Does a Shipyard HQ listing provide a dofollow link?","answer":"No — links are nofollow redirects on their own domain, rated 33."},{"question":"Do I need to link back to Shipyard HQ?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published."}]', rw_summary='Shipyard HQ is a free nofollow launch with no outbound link but real analytics, forgoing a backlink. Domain rating is 33.', rw_fact_points='["No published review time","Free launch with nofollow redirect","No required backlink","Accepts indie products and SaaS"]', rw_submission_checks='["No link passes to your domain.","The value is free analytics.","Sign-in is a separate console."]', rw_seo_title='Shipyard HQ: Free Analytics Launch, DR 33', rw_seo_description='How to launch on Shipyard HQ: free nofollow launch with analytics, no backlink. Redirect from the 2026-11-16 snapshot.' WHERE slug='shipyard-hq';
UPDATE submission_sites SET rw_source_lead='A startup tools directory with one price and no free lane, $30 once, that takes payment before asking a single thing about the product.', rw_what_you_get='A dofollow listing with no backlink for $30 once, paid before the form is even shown.', rw_you_need='["$30 — there is no other route","A product their editors judge fit for a startup audience"]', rw_eligibility='You need to pay and a fitting product. A zero budget, or anything judged a poor fit, is out — poor fits are rejected and refunded.', rw_submit_steps='["1 Open the submit page. It holds the whole offer: one price, two add-ons and a rejection clause.","2 Pay first. Purchase Tool Listing is $30; their own line says tool details are collected after payment.","3 Fill in the details. Everything about the product is asked for once payment is through, so the form cannot be read beforehand."]', rw_submit_requirements='["A $30 one-time payment before any form","A product name and URL and tags collected afterward","Featured placement optional"]', rw_rejection_reasons='["A zero budget, and anything editors judge a poor fit — rejected and refunded"]', rw_gotchas='["Payment comes before the form, their page states outright, so nothing about what will be asked can be checked before spending $30.","They reserve the right to reject a tool as a poor fit and refund the fee, so the $30 is at risk of a round trip rather than a certain listing.","Two optional add-ons sit alongside: Featured Large $45 for a month in the top carousel and Featured Small $30 for a smaller card."]', rw_faq='[{"question":"How long does Stratup.ai approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to Stratup.ai?","answer":"$30 once for a permanent listing — the only way in. Featured Large $45 or Featured Small $30 a month are optional add-ons."},{"question":"Does a Stratup.ai listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 33."},{"question":"Do I need to link back to Stratup.ai?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A zero budget or a product judged a poor fit — the fee is refunded."}]', rw_summary='Stratup.ai is a paid-only $30 dofollow startup directory with no backlink, where payment precedes the form. Domain rating is 33.', rw_fact_points='["No published review time","Paid-only at $30, dofollow","No badge or return link is expected","Accepts startup tools and SaaS"]', rw_submission_checks='["Payment comes before the form.","Poor fits are rejected and refunded.","Featured add-ons are optional."]', rw_seo_title='Stratup.ai: $30 Dofollow Listing, DR 33', rw_seo_description='How to submit to Stratup.ai: $30 one-time dofollow listing, no backlink. Pay-before-form from the 2026-11-16 snapshot.' WHERE slug='stratup-ai';
UPDATE submission_sites SET rw_source_lead='Not a listing so much as a feedback exchange: you ask one question, reviewers answer, and you earn credits by reviewing back.', rw_what_you_get='A nofollow feedback request with no outbound link, where credits earned by reviewing others drive the exchange.', rw_you_need='["A live HTTPS product link — previews and repos are rejected","An account created at submit time, a cover image and one clear question"]', rw_eligibility='You need a live product and a real question. Preview URLs and bare GitHub repositories are refused by name.', rw_submit_steps='["1 Prefill from your URL. Paste the product URL and press Prefill project; they populate what they can from the page.","2 Write the ask: a name up to 100, a description up to 1,000 and a feedback question up to 240. Choose up to five of fourteen focus areas to route the request in their Review Queue.","3 Add a required cover image — the error only appears after you try to submit — and at least one platform.","4 Sign in and submit. The button reads Login & Submit; the form is kept through sign-in and submitted automatically on return."]', rw_submit_requirements='["A live HTTPS product URL and a cover image","A project name and a feedback question up to 240","Up to five focus areas and at least one platform","An optional description and social handles"]', rw_rejection_reasons='["Preview URLs and bare GitHub repositories"]', rw_gotchas='["There is no outbound link on the project pages opened, so this is feedback and community, not a backlink.","It runs on credits: two on signup, two more when the first project is approved, and more by reviewing others — submitting means joining an exchange.","The cover image is required but not marked until submit, so the first attempt fails after everything else is filled."]', rw_faq='[{"question":"How long does VibeCodingList approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to VibeCodingList?","answer":"Submitting is free with an account and credits."},{"question":"Does a VibeCodingList listing provide a dofollow link?","answer":"No — nofollow on a domain rated 34, with no outbound link on project pages."},{"question":"Do I need to link back to VibeCodingList?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Preview URLs and bare GitHub repositories."}]', rw_summary='VibeCodingList is a free nofollow feedback exchange with no outbound link or backlink, driven by review credits. Domain rating is 34.', rw_fact_points='["No published review time","Free listing with no backlink","Credits govern participation","Accepts live indie products"]', rw_submission_checks='["No link passes — this is feedback.","Credits come from reviewing others.","The cover image is hidden-required."]', rw_seo_title='VibeCodingList: Free Feedback Exchange, DR 34', rw_seo_description='How to submit to VibeCodingList: free nofollow feedback exchange, no backlink. Credit system from the 2026-11-16 snapshot.' WHERE slug='vibecodinglist';
UPDATE submission_sites SET rw_source_lead='A paid review site that syndicates the write-up across four sister blogs, with no price until you enquire.', rw_what_you_get='A dofollow written review, pinned or syndicated across sister sites, priced only after you make contact.', rw_you_need='["A payment quoted on enquiry and an app worth reviewing"]', rw_eligibility='You need to pay. Both products are paid reviews, not a listing row, and a genuine rating may be unflattering.', rw_submit_steps='["1 Read the two products. Featured Review is a guaranteed rating and review, posted permanently and pinned on the home page for at least thirty days. Network Review republishes it as unique articles across four sister sites.","2 Enquire. No price is printed and no form takes payment; the route is their submission page and then email."]', rw_submit_requirements='["A payment quoted on enquiry","An app URL and reviewer access"]', rw_rejection_reasons='["Anything expecting a free listing — both products are paid reviews with no directory row"]', rw_gotchas='["Neither product has a price on the page, so the cost only arrives after you make contact.","What you buy is a review with a rating, and they say the rating is genuine — a paid placement can still read badly.","The Network option publishes different articles about the same product across four sites they own — worth understanding before judging the value."]', rw_faq='[{"question":"How long does WebAppRater approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to WebAppRater?","answer":"Two paid products, neither priced on the page: a Featured Review pinned for thirty days, and a Network Review syndicated across their sites. Prices by enquiry."},{"question":"Does a WebAppRater listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 34."},{"question":"Do I need to link back to WebAppRater?","answer":"No backlink is required."},{"question":"What gets a submission rejected?","answer":"Expecting a free listing — both products are paid reviews."}]', rw_summary='WebAppRater is a paid enquiry-only dofollow review service with no backlink, syndicating write-ups across sister sites. Domain rating is 34.', rw_fact_points='["No published review time","Paid by enquiry, dofollow","No badge or return link is expected","Accepts web and mobile apps"]', rw_submission_checks='["The price comes after contact.","The rating is genuine and may be negative.","Network publishes across four owned sites."]', rw_seo_title='WebAppRater: Paid Review, DR 34', rw_seo_description='How to submit to WebAppRater: paid dofollow review by enquiry, no backlink. Syndication from the 2026-11-16 snapshot.' WHERE slug='webapprater';
UPDATE submission_sites SET rw_source_lead='A web design gallery whose free lane needs no account and still leaves a bare followed link.', rw_what_you_get='A dofollow gallery listing for a screenshot cut to exactly 1480x900, free with no account and no captcha.', rw_you_need='["A screenshot exactly 1480x900 and a live site URL","An email and at least one category, colour and tag","A developer name, website and country"]', rw_eligibility='You need a site with a screenshot worth showing and one that captures at the single accepted size.', rw_submit_steps='["1 Take the free lane, not the one the site offers. The header Submit goes to a pricing page; Free Submission is a separate form with its own route.","2 Fill the website details: a name, URL, email and three required multi-selects — a category of 44, a colour of 11 and tags of 50, each taking more than one value.","3 Upload the screenshot. The dropzone prints the required size, 1480x900, and previews immediately.","4 Name the developer: a name, website and country are all required, all describing the person who built the site. Eight social URL fields follow, all optional.","5 Submit. One button, no captcha, no account; the page confirms in place with an estimated time of one week."]', rw_submit_requirements='["A website name, URL and email and a screenshot exactly 1480x900","One or more categories, colours and tags and a description","A developer name, website and country and optional social URLs"]', rw_rejection_reasons='["A site with no screenshot worth showing, and a page that cannot be captured at 1480x900"]', rw_gotchas='["The free form has its own route and nothing in the header points at it — the Submit control goes to pricing where free is the third option behind a separate form.","The screenshot must be exactly 1480x900, printed only in the dropzone — a 1200x630 social card is the wrong shape.","The developer block asks for a person''s name, site and country as required fields; on a solo product that is you, and the country field is free text."]', rw_faq='[{"question":"How long does WebsURL approval take?","answer":"About a week — the confirmation page estimates one week."},{"question":"How much does it cost to submit to WebsURL?","answer":"The free lane costs nothing and has its own form. Paid: $10 Premium listed within 24 hours and $99 for a done-for-you push to 65 other galleries."},{"question":"Does a WebsURL listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 34."},{"question":"Do I need to link back to WebsURL?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"A weak screenshot or one not captured at 1480x900."}]', rw_summary='WebsURL is a free no-account dofollow design gallery for sites shot at exactly 1480x900. No backlink; DR 34.', rw_fact_points='["About a week to approve","Free listing with a dofollow link","No required backlink","Accepts designed websites"]', rw_submission_checks='["The free form has a hidden separate route.","The screenshot must be exactly 1480x900.","Developer name, site and country are required."]', rw_seo_title='WebsURL: Free Design Gallery, DR 34', rw_seo_description='How to submit to WebsURL: free no-account dofollow design listing, no backlink. Exact screenshot size from the 2026-11-16 snapshot.' WHERE slug='websurl';
UPDATE submission_sites SET rw_source_lead='A third deployment of the open-source Open-Launch code, with two free slots a day and a 2,000-character floor on the description.', rw_what_you_get='A nofollow launch slot with a 2,000-word-plus description requirement and a free calendar booked six months out.', rw_you_need='["An account via Google in one click","A description of at least 2,000 characters and a logo under 1MB"]', rw_eligibility='You need the long copy and a date. Anything under 2,000 characters will not pass step one, and a slot inside six months on free does not exist.', rw_submit_steps='["1 Sign in. Google is the only option and creates the account in one click.","2 Project Info: a name, URL, a short description, then the full description with its 2,000-character floor, then a logo and optional product image as file uploads.","3 Details: up to three categories, up to five tech tags, platforms, pricing and optional GitHub and Twitter URLs.","4 Launch Date: Free or Premium $9, then a date from a 180-day calendar that greys out days with no slots.","5 Review and submit. The page is public immediately, marked Coming Soon until the date."]', rw_submit_requirements='["An account and a product name and short description","A full description of at least 2,000 characters","A 1:1 logo under 1MB and up to three categories","Up to five tech tags and an optional 16:9 product image"]', rw_rejection_reasons='["Fewer than 2,000 characters — the form will not advance — and needing a slot inside six months on free"]', rw_gotchas='["The full description will not accept under 2,000 characters, several times what most boards want and more than a pack is likely to hold — budget the writing.","The free calendar shows 180 days and opens exactly one, the furthest, six months out; every earlier day has zero slots.","A free listing needs a top-three finish AND their badge for a followed link — the badge alone guarantees nothing.","The site''s pricing page sells music-generator credits and never mentions launches; the launch prices exist only inside the submission flow."]', rw_faq='[{"question":"How long does YourFirstApp approval take?","answer":"Six months or more — the free calendar opens only its furthest day."},{"question":"How much does it cost to submit to YourFirstApp?","answer":"Free with two slots a day and 180 days of scheduling; $9 Premium skips the queue, promises dofollow from day one and has ten slots a day. The public pricing page sells unrelated credits."},{"question":"Does a YourFirstApp listing provide a dofollow link?","answer":"No by default — nofollow on a domain rated 34; free needs top-three plus badge."},{"question":"Do I need to link back to YourFirstApp?","answer":"No required backlink, though the badge is one of two conditions for free dofollow."},{"question":"What gets a listing rejected?","answer":"A description under 2,000 characters or needing a near-term free slot."}]', rw_summary='YourFirstApp is a free nofollow Open-Launch board with a 2,000-character minimum and a free calendar open only six months out. DR 34.', rw_fact_points='["Free slot six months out","Free link nofollow; top-three plus badge for dofollow","No required backlink","Accepts apps and SaaS"]', rw_submission_checks='["Write 2,000 characters before starting.","Only the furthest free date is open.","The badge alone does not earn the follow."]', rw_seo_title='YourFirstApp: Free Dated Launch, DR 34', rw_seo_description='How to launch on YourFirstApp: free nofollow slot six months out, 2,000-character rule. Rules from the 2026-11-16 snapshot.' WHERE slug='yourfirstapp';
UPDATE submission_sites SET rw_source_lead='A general web directory where a listing costs $49 and the only free route is writing them an article.', rw_what_you_get='A dofollow listing for $49, or a free blog guest post of 500 words that is not a directory entry.', rw_you_need='["$49 for a listing, or a 500-word article","A site relevant to one named category with original content"]', rw_eligibility='You need a real site with original content in one category. Affiliate-only, value-free and traffic-destination sites are refused.', rw_submit_steps='["1 Pick the category first. Their guide says to browse and identify the single best category before submitting; the Submit URL link sits inside that category.","2 Open the submission page. Submit URL runs a JavaScript call rather than an href, landing on a form page with no guessable direct URL.","3 Choose what you are buying: a $49 featured listing, a free or $19 guest post, a $69 written post or a $99 listing-plus-article. None is a plain free directory listing."]', rw_submit_requirements='["A $49 listing payment and a website URL","A category of sixteen chosen before submitting","An optional 500-word article for their blog"]', rw_rejection_reasons='["Affiliate-only sites, sites with no original content or added value, and anything whose only purpose is driving traffic elsewhere"]', rw_gotchas='["Nothing lists a site for nothing — the no-fee route is a 500-word guest post on their blog, not a directory listing.","The Submit URL control is a JavaScript call with no href, so the form cannot be reached by typing a URL and a crawler will not find it.","The footer still reads 2003 to 2025 with nothing newer, worth checking before paying a $49 one-time fee."]', rw_faq='[{"question":"How long does 01Webdirectory approval take?","answer":"Three to five days."},{"question":"How much does it cost to submit to 01Webdirectory?","answer":"$49 once for a featured listing with up to four deep links. A 500-word guest post is free, $19 for three-day review or $69 written for you; listing plus article $99."},{"question":"Does a 01Webdirectory listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 31."},{"question":"Do I need to link back to 01Webdirectory?","answer":"No backlink is required."},{"question":"What gets a site rejected?","answer":"Affiliate-only, value-free or traffic-destination sites."}]', rw_summary='01Webdirectory is a paid $49 dofollow general directory with no backlink, where the only free route is a guest post rather than a listing. DR 31.', rw_fact_points='["Three-to-five-day review","Paid-only listing at $49, dofollow","No badge or return link is expected","Accepts general websites"]', rw_submission_checks='["The free route is a blog post, not a listing.","The submit page has no direct URL.","The site looks dated — verify before paying."]', rw_seo_title='01Webdirectory: $49 Dofollow Listing, DR 31', rw_seo_description='How to submit to 01Webdirectory: $49 dofollow listing, no backlink. Free route is a guest post — 2026-11-16 snapshot.' WHERE slug='01webdirectory';
UPDATE submission_sites SET rw_source_lead='Badge first, then you pick a launch date out of five free slots a day.', rw_what_you_get='A dofollow launch on a chosen date, rented against a badge that is checked before launch and again after publishing.', rw_you_need='["An account via Google, GitHub or email","Their badge live on your site for free","A 1:1 icon and a 16:9 image, both under 1MB, and a live URL"]', rw_eligibility='You need an account, both images and a site that keeps the badge up. A free launch without the badge, or without the two images, is out.', rw_submit_steps='["1 Sign in. The submit route bounces to login offering Google and GitHub above an email-and-password form.","2 Fill the details screen: a link, a name, up to three categories and five tags from searchable popovers, a description, a Markdown introduction, then a 1:1 icon and a 16:9 image.","3 Verify the badge. The free card reads Verify backlink first and offers light, dark and text-link snippets; paste your homepage URL and press Verify Backlink.","4 Choose a launch date. Submit Project opens a calendar with five free slots a day from tomorrow; picking one schedules the launch for 00:00 UTC."]', rw_submit_requirements='["An account and their badge kept live after launch","A product URL, name, description and Markdown introduction","Up to three categories and five tags","A 1:1 icon and a 16:9 image, each under 1MB"]', rw_rejection_reasons='["A free launch on a site that will not keep the badge up — rechecked before and after launch — and missing the two required images"]', rw_gotchas='["The badge is not a one-off check — they re-check before launch and may verify again after publishing, so taking it down can cost the listing.","The free calendar has five slots a day and paid tiers sell on skipping it, so a wanted date may already be full.","The badge step sits between filling the form and choosing a date — stopping after the details screen schedules nothing."]', rw_faq='[{"question":"How long does AiIndex.tools approval take?","answer":"One to two days, at the chosen launch date."},{"question":"How much does it cost to submit to AiIndex.tools?","answer":"Free with a badge and five slots a day. Pro $9.90 once drops the badge and skips the queue; Sponsor $19.90 buys thirty days of site-wide placement."},{"question":"Does an AiIndex.tools listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 32."},{"question":"Do I need to link back to AiIndex.tools?","answer":"Yes — a badge is required on free and rechecked after publishing."},{"question":"What gets a listing rejected?","answer":"Removing the badge or omitting either required image."}]', rw_summary='AiIndex.tools is a free dofollow launch board with a chosen date, a five-slot daily badge gate and no other backlink. DR 32.', rw_fact_points='["Launch in one to two days","Dofollow link rented against a badge","Badge rechecked before and after launch","Accepts AI tools and SaaS"]', rw_submission_checks='["The badge is checked twice.","A wanted date may be full.","Filling details alone schedules nothing."]', rw_seo_title='AiIndex.tools: Free Badge Launch, DR 32', rw_seo_description='How to launch on AiIndex.tools: free dofollow listing for a badge, five daily slots. Badge rechecks from the 2026-11-16 snapshot.' WHERE slug='aiindex-tools';
UPDATE submission_sites SET rw_source_lead='One of sixteen sister directories: free for a badge that links to your own listing URL, verified before the form opens.', rw_what_you_get='A dofollow listing gated behind a badge pointing at your reserved listing URL.', rw_you_need='["A live URL and a Google account","A screenshot under 10MB and a square icon under 5MB","Their badge on your site linking to your listing URL"]', rw_eligibility='You need an account, media and a site that will carry the badge. Nothing is published beyond a review for quality, clarity and fit.', rw_submit_steps='["1 Log in with Google — the only sign-in.","2 Website. Enter the product homepage and press Generate Badge; the light or dark 54px badge must link to the listing URL built from your domain.","3 Badge. Put it on your homepage or footer, enter the page URL under Website URL to Check and press Verify Badge — a pass opens the details step.","4 Details: a site name, screenshot, icon, up to four categories, a pricing model, a 150-character summary and a 1,500-character About, then terms and Submit for Review."]', rw_submit_requirements='["A website URL and a badge linking to the listing URL","A site name, a screenshot under 10MB and a square icon under 5MB","Up to four categories, a 150-character summary and a 1,500-character About"]', rw_rejection_reasons='["Nothing published beyond a review for quality, clarity and fit"]', rw_gotchas='["The badge must link to the exact listing URL built from your domain, not the homepage — a generic badge fails the check and the details form never opens.","It is one of sixteen sister directories on one codebase, and a banner on every page sells the operator''s paid submission service, which is not this listing.","No review window is stated; the success page only says the product is in review."]', rw_faq='[{"question":"How long does App Networker approval take?","answer":"No review time is published."},{"question":"How much does it cost to submit to App Networker?","answer":"Submitting is free with a badge."},{"question":"Does an App Networker listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 32."},{"question":"Do I need to link back to App Networker?","answer":"Yes — a badge is required."},{"question":"What gets a listing rejected?","answer":"Nothing published beyond a quality, clarity and fit review."}]', rw_summary='App Networker is a free dofollow directory gated on a badge linking to your reserved listing URL, with no other backlink. DR 32.', rw_fact_points='["No published review time","Free listing with a dofollow link","Badge gates the form","Accepts SaaS, web apps and AI tools"]', rw_submission_checks='["Point the badge at the listing URL, not the homepage.","Reach overlaps with fifteen sister sites.","No review window is published."]', rw_seo_title='App Networker: Free Badge Listing, DR 32', rw_seo_description='How to submit to App Networker: free dofollow listing gated on a badge to your reserved URL. Rules from the 2026-11-16 snapshot.' WHERE slug='appnetworker';
UPDATE submission_sites SET rw_source_lead='Weekly launch board where the free queue costs ten karma of upvoting, and $9 buys the week you want.', rw_what_you_get='A free launch bought with ten karma points and a community queue, or $9 for the week you want and a followed link.', rw_you_need='["A live URL and a Google or email account","A 500x500 logo and three cover images","Ten karma for the free lane"]', rw_eligibility='You need the account, the media and ten karma. Nothing is published about who is refused.', rw_submit_steps='["1 Sign in. Continue with Google in a popup or email and password, behind a Cloudflare check that passes on its own.","2 The form: a name up to 45, a URL, a tagline up to 60, up to three categories, pricing, optional collaborators and an open-source box, Built with from a list, a description up to 5,000, a 500x500 logo and three to four 1200x630 covers. A completion meter must read 100% before Submit Product is enabled.","3 Choose your launch strategy. Submit Product creates the product and opens the plan page: Free Launch for 10 karma or Premium $9.","4 Join Queue. With ten karma the free card reads Join Queue and a dialog lists weeks with open spots; Confirm Launch Date schedules it and spends the karma."]', rw_submit_requirements='["A product name up to 45, a URL and a tagline up to 60","Up to three categories and Built-with tags, and a description up to 5,000","A 500x500 logo and three to four 1200x630 covers","Ten karma for the free lane"]', rw_rejection_reasons='["Nothing published about who is refused"]', rw_gotchas='["The free lane costs karma — ten points, which took a completed profile, an upvote and six more claimed by hand on the Karma Center, and the launch spends them.","The free queue fills weeks ahead — the next four were full and the first open slot five weeks out, so free is a date, not a review.","The plan card says free links are nofollow with dofollow only for the week''s top three, while live product links read as followed — which you get is not checkable before launch.","Submit Product does not submit — it creates the product and sends you to the plan page."]', rw_faq='[{"question":"How long does BuiltByIndies approval take?","answer":"Three to six months; the free queue books weeks ahead."},{"question":"How much does it cost to submit to BuiltByIndies?","answer":"Free with ten karma and a community queue, with dofollow only for the week''s top three. $9 Premium picks the week, publishes instantly with followed links and thirty days of homepage sponsorship."},{"question":"Does a BuiltByIndies listing provide a dofollow link?","answer":"The plan card says nofollow on free with top-three dofollow; live links read otherwise — no clear answer."},{"question":"Do I need to link back to BuiltByIndies?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"Nothing published."}]', rw_summary='BuiltByIndies is a weekly launch board where free costs ten karma and a long queue, while $9 buys the week and a followed link. DR 32.', rw_fact_points='["Free launch needs ten karma","Free link nominally nofollow; $9 guarantees dofollow","No required backlink","Accepts indie products and SaaS"]', rw_submission_checks='["Karma takes real upvoting to earn.","The free queue books weeks out.","Submit Product is not a launch."]', rw_seo_title='BuiltByIndies: Karma Launch Board, DR 32', rw_seo_description='How to launch on BuiltByIndies: free needs ten karma and a long queue, $9 buys the week. Rules from the 2026-11-16 snapshot.' WHERE slug='builtbyindies';
UPDATE submission_sites SET rw_source_lead='€49 once for a listing reviewed within 48 hours, with their badge on your landing page as step one.', rw_what_you_get='A dofollow listing for €49 with a 48-hour manual review — and a badge required on your landing page.', rw_you_need='["A live URL, €49 and their badge on your landing page"]', rw_eligibility='You need to pay, a live tool and a site that will carry the badge. Nothing is published beyond a manual quality check.', rw_submit_steps='["1 Add the badge. Step 1 on the submit page asks you to copy a pink badge embed and put it on your landing page.","2 Pay and submit. Step 2 is Pay €49 to Submit via Stripe; the tool details come after payment.","3 Review. Paid submissions are manually checked within 48 hours."]', rw_submit_requirements='["Their badge on your landing page and a €49 one-time Stripe payment","A tool URL and the details asked after payment"]', rw_rejection_reasons='["Nothing published beyond a manual quality check"]', rw_gotchas='["There is no free lane and the badge is asked for before payment — the price is €49 plus a badge, not one or the other.","They say only a limited number of listings are accepted each week and say nothing about what happens to a paid submission that misses the cut."]', rw_faq='[{"question":"How long does Listmyai approval take?","answer":"One to two days; paid submissions are reviewed within 48 hours."},{"question":"How much does it cost to submit to Listmyai?","answer":"€49 once via Stripe with no free lane: featured placement, 48-hour review and a limited weekly intake."},{"question":"Does a Listmyai listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 31."},{"question":"Do I need to link back to Listmyai?","answer":"Yes — their badge is required on your landing page."},{"question":"What gets a listing rejected?","answer":"Nothing published beyond a manual quality check."}]', rw_summary='Listmyai is a paid-only €49 dofollow AI directory with 48-hour review, requiring a badge and no other backlink. DR 31.', rw_fact_points='["48-hour manual review","Paid-only at €49, dofollow","A badge is required","Accepts AI tools"]', rw_submission_checks='["The badge comes before payment.","Weekly intake is capped.","No free lane exists."]', rw_seo_title='Listmyai: €49 Dofollow Listing, DR 31', rw_seo_description='How to submit to Listmyai: €49 once for a dofollow listing, no backlink. Badge first from the 2026-11-16 snapshot.' WHERE slug='listmyai';
UPDATE submission_sites SET rw_source_lead='One URL field and a crawler write the listing, then it sits in a queue nine weeks deep.', rw_what_you_get='A dofollow listing written entirely from your landing page, with a long free queue and a visible queue position.', rw_you_need='["A live URL their crawler can read","An account which Google SSO creates on the spot"]', rw_eligibility='You need a crawlable site and independent software — the directory is makers and solopreneurs by its own description.', rw_submit_steps='["1 Paste the URL. The form has one field; the name, description, visuals and feature list are all extracted by their crawler after submit.","2 Sign in when the button asks. Nothing says an account is needed until Submit SaaS opens a modal with Continue with Google above an email-and-password form.","3 Let the consent screen return you. Approving Google posts the submission in the same movement and lands on a thank-you page with a submission id.","4 Read the queue position. The page shows the position, an estimated review date and five pipeline stages; a $9 upsell offers review within 24 hours."]', rw_submit_requirements='["A live website URL and an account via Google or email and password"]', rw_rejection_reasons='["Anything the crawler cannot read, since the whole listing comes from your page, and anything that is not independent software"]', rw_gotchas='["The free queue is long and stated in numbers — one September submission landed at position 687 with a November estimate, because the owner reviews ten a day by hand.","The account requirement is invisible until you press Submit; the form accepts a URL signed out and the modal only opens on click.","Everything about the listing is written by the crawler from your site — there is no field to write your own tagline or description."]', rw_faq='[{"question":"How long does MicroSaaS Directory approval take?","answer":"Two to three months; one submission waited from September to November."},{"question":"How much does it cost to submit to MicroSaaS Directory?","answer":"Free with a long queue; $9 moves you to the front with a 24-hour review and a week of site-wide ads. Sidebar ads sell at $29 a month or $9 a week."},{"question":"Does a MicroSaaS Directory listing provide a dofollow link?","answer":"Yes, a dofollow link on a domain rated 31."},{"question":"Do I need to link back to MicroSaaS Directory?","answer":"No backlink is required."},{"question":"What gets a listing rejected?","answer":"A site the crawler cannot read, or a product that is not independent software."}]', rw_summary='MicroSaaS Directory is a free dofollow indie-SaaS directory with no backlink, where a crawler writes the listing and the free queue runs months deep. DR 31.', rw_fact_points='["Free queue of two to three months","Free listing with a dofollow link","No required backlink","Accepts indie and micro SaaS"]', rw_submission_checks='["The queue is publicly numbered and long.","Sign-in is hidden until submit.","The crawler owns your listing copy."]', rw_seo_title='MicroSaaS Directory: Free Crawled Listing, DR 31', rw_seo_description='How to submit to MicroSaaS Directory: free dofollow listing written by a crawler, no backlink. Long queue from the 2026-11-16 snapshot.' WHERE slug='microsaas-directory';
